    '彼は会社のために尽くしてきた。' => 'Kare wa kaisha no tame ni tsukushite kita.',
    '私たちは地球環境のために何ができるだろうか。' => 'Watashitachi wa chikyuu kankyou no tame ni nan ga dekirudarou ka.',
    '家族のように、一生懸命働いている。' => 'Kazoku no you ni, isshou kenmei hataraite iru.',
    'Tujuan Negatif Formal: 〜ないために' => 'Tujuan Negatif Formal: nai tame ni',
    '失敗しないために、計画をしっかり立てた。' => 'Shippai shinai tame ni, keikaku wo shikkari tateta.',
