    'Akibat Negatif dari Tindakan Lalu: 〜たために' => 'Akibat Negatif dari Tindakan Lalu: ta tame ni',
    '準備を怠ったために、試験に落ちてしまった。' => 'Junbi wo okotatta tame ni, shiken ni ochite shimatta.',
    '無理をしたために、体を壊してしまった。' => 'Muri wo shita tame ni, karada wo kowashite shimatta.',
    '彼は嘘をついたために、みんなの信頼を失った。' => 'Kare wa uso wo tsuita tame ni, minna no shinrai wo ushinatta.',
