    'Penghubung Antarkalimat: このため' => 'Penghubung Antarkalimat: kono tame',
    '昨夜、大雨が降った。このため、川の水位が上がっている。' => 'Sakuya, ooame ga futta. kono tame, kawa no suii ga agatte iru.',
