    '大雨が降った。このためで、川の水位が上がった。' => 'Ooame ga futta. kono tame de, kawa no suii ga agatta.',
    'Kesimpulan Logis Alami: 〜わけだ' => 'Kesimpulan Logis Alami: wake da',
