    '今日は祝日だ。道理で銀行が閉まっているわけだ。' => 'Kyou wa shukujitsu da. douri de ginkou ga shimatte iru wake da.',
    '彼女はフランス人と結婚した。それでフランス語が話せるわけだ。' => 'Kanojo wa Furansunin to kekkon shita. sore de Furansu go ga hanaseru wake da.',
    '毎日3時間も練習しているのだから、上達するわけだ。' => 'Mainichi 3 jikan mo renshuu shite iru no dakara, joutatsu suru wake da.',
