    'Kemustahilan Kuat: 〜わけがない' => 'Kemustahilan Kuat: wake ga nai',
    'こんな難しい問題、子供に解けるわけがない。' => 'Konna muzukashii mondai, kodomo ni tokeru wake ga nai.',
    '彼が嘘をつくわけがない。彼はとても正直な人だ。' => 'Kare ga uso wo tsuku wake ga nai. kare wa totemo shoujiki na hito da.',
