    'Penyangkalan Sebagian: 〜わけではない' => 'Penyangkalan Sebagian: wake de wa nai',
    '嫌いなわけではないが、あまり食べたくない。' => 'Kirai na wake de wa naiga, amari tabetaku nai.',
    '全員が反対しているわけではない。' => 'Zen\'in ga hantai shite iru wake de wa nai.',
    'お金がないわけではないが、今は使いたくない。' => 'Okane ga nai wake de wa naiga, ima wa tsukaitaku nai.',
