    '嫌いなわけではない、あまり食べたくない。' => 'Kirai na wake de wa nai, amari tabetaku nai.',
    'Varian Lembut Penyangkalan: 〜わけでもない' => 'Varian Lembut Penyangkalan: wake de mo nai',
    '特に好きなわけでもないが、嫌いなわけでもない。' => 'Tokuni suki na wake de mo naiga, kirai na wake de mo nai.',
    '毎日運動しているわけでもないのに、彼は健康だ。' => 'Mainichi undou shite iru wake de mo nai no ni, kare wa kenkou da.',
    '高いわけでもないのに、あの店はあまり人気がない。' => 'Takai wake de mo nai no ni, ano mise wa amari ninki ga nai.',
    'お金持ちなわけでもないのに、いつも高級な物を買っている。' => 'Okanemochi na wake de mo nai no ni, itsu mo koukyuu na mono wo katte iru.',
