    'Penyangkalan Ganda: 〜ないわけではない' => 'Penyangkalan Ganda: nai wake de wa nai',
    '忙しいが、時間がないわけではない。' => 'Isogashiiga, jikan ga nai wake de wa nai.',
    '値段が高くて買わないが、買えないわけではない。' => 'Nedan ga takakute kawanaiga, kaenai wake de wa nai.',
    '彼を信じていないわけではない。ただ、少し心配なだけだ。' => 'Kare wo shinjite inai wake de wa nai. tada, sukoshi shinpai na dake da.',
    '行きたくないわけではないが、今回は都合が悪い。' => 'Ikitaku nai wake de wa naiga, konkai wa tsugou ga warui.',
    '時間がないわけがない。' => 'Jikan ga nai wake ga nai.',
    'Kesimpulan Meringkas: 〜というわけだ' => 'Kesimpulan Meringkas: to iu wake da',
    'つまり、彼は最初から知っていたというわけだ。' => 'Tsumari, kare wa saisho kara shitte ita to iu wake da.',
    '電車が止まっていた。道理で誰も駅にいないというわけだ。' => 'Densha ga tomatte ita. douri de dare mo eki ni inai to iu wake da.',
    '彼女は毎日料理の練習をしている。将来、シェフになりたいというわけだ。' => 'Kanojo wa mainichi ryouri no renshuu wo shite iru. shourai, shefu ni naritai to iu wake da.',
    '結局、二人はお金のことで喧嘩したというわけだ。' => 'Kekkyoku, futari wa okane no koto de kenka shita to iu wake da.',
    'つまり、彼は最初から知っているというわけがある。' => 'Tsumari, kare wa saisho kara shitte iru to iu wake ga aru.',
    'Tidak Bisa Begitu Saja: 〜わけにはいかない' => 'Tidak Bisa Begitu Saja: wake ni wa ikanai',
    '明日は大事な会議があるので、休むわけにはいかない。' => 'Ashita wa daiji na kaigi ga aru no de, yasumu wake ni wa ikanai.',
    '友達に借りたお金を返さないわけにはいかない。' => 'Tomodachi ni karita okane wo kaesanai wake ni wa ikanai.',
    'まだ仕事が残っているので、先に帰るわけにはいかない。' => 'Mada shigoto ga nokotte iru no de, saki ni kaeru wake ni wa ikanai.',
    '約束したのだから、行かないわけにはいかない。' => 'Yakusoku shita no dakara, ikanai wake ni wa ikanai.',
    '休みますわけにはいかない。' => 'Yasumimasu wake ni wa ikanai.',
    'Entah Kenapa: どういうわけか' => 'Entah Kenapa: dou iu wake ka',
    'どういうわけか、今日は誰も来なかった。' => 'Dou iu wake ka, kyou wa dare mo konakatta.',
    'どういうわけか、最近よく眠れない。' => 'Dou iu wake ka, saikin yoku nemurenai.',
    'どういうわけか、彼はいつも遅刻する。' => 'Dou iu wake ka, kare wa itsu mo chikoku suru.',
    'どういうわけか、財布がどこにも見つからない。' => 'Dou iu wake ka, saifu ga doko ni mo mitsukaranai.',
    'どんなわけか、今日は誰も来なかった。' => 'Donna wake ka, kyou wa dare mo konakatta.',
    'Transisi Oleh Karena Itu: そういうわけで' => 'Transisi Oleh Karena Itu: sou iu wake de',
    '実は来月引っ越すことになりました。そういうわけで、この仕事は今月で辞めます。' => 'Jitsu wa raigetsu hikkosu koto ni narimashita. sou iu wake de, kono shigoto wa kongetsu de yamemasu.',
    '電車が事故で止まってしまって。そういうわけで、遅れてすみません。' => 'Densha ga jiko de tomatte shimatte. sou iu wake de, okurete sumimasen.',
    '両親が急に来ることになって。そういうわけで、今日は参加できません。' => 'Ryoushin ga kyuu ni kuru koto ni natte. sou iu wake de, kyou wa sanka dekimasen.',
    '予算が足りなくなってしまいました。そういうわけで、計画を変更することにしました。' => 'Yosan ga tarinaku natte shimaimashita. sou iu wake de, keikaku wo henkou suru koto ni shimashita.',
    '実は来月引っ越すことになりました。そういうわけが、この仕事は今月で辞めます。' => 'Jitsu wa raigetsu hikkosu koto ni narimashita. sou iu wake ga, kono shigoto wa kongetsu de yamemasu.',
    'Ada Alasan Tertentu: わけがある' => 'Ada Alasan Tertentu: wake ga aru',
    '彼が急に会社を辞めたのには、わけがあるはずだ。' => 'Kare ga kyuu ni kaisha wo yameta no ni wa, wake ga aru hazu da.',
    '何も言わずに帰ったのには、何かわけがあるのだろう。' => 'Nan mo iwazu ni kaetta no ni wa, nan ka wake ga aru no darou.',
    '彼女が毎日遅くまで残業しているのには、わけがある。' => 'Kanojo ga mainichi osoku made zangyou shite iru no ni wa, wake ga aru.',
    '突然電話を切ったのには、きっとわけがある。' => 'Totsuzen denwa wo kitta no ni wa, kitto wake ga aru.',
    '彼が急に会社を辞めたのは、わけがある。' => 'Kare ga kyuu ni kaisha wo yameta no wa, wake ga aru.',
    'Ungkapan Penyesalan dengan 〜ばよかった' => 'Ungkapan Penyesalan dengan ba yokatta',
    'もっと早く起きればよかった。' => 'Motto hayaku okireba yokatta.',
    'あの時、彼に本当のことを言えばよかった。' => 'Ano toki, kare ni hontou no koto wo ieba yokatta.',
    'こんなに混むなら、もっと早く出発すればよかったなあ。' => 'Konna ni komunara, motto hayaku shuppatsu sureba yokatta naa.',
    '傘を持ってくればよかった。今、雨に濡れている。' => 'Kasa wo motte kureba yokatta. ima, ame ni nurete iru.',
    'もっと勉強すればいいでした。' => 'Motto benkyou sureba iideshita.',
    'Pola 〜ば〜ほど: Semakin...Semakin...' => 'Pola baa hodo: Semakin...Semakin...',
    '練習すればするほど、上手になります。' => 'Renshuu sureba suru hodo, jouzu ni narimasu.',
    'この漢字は書けば書くほど覚えやすくなる。' => 'Kono kanji wa kakeba kaku hodo oboeyasuku naru.',
    '値段は安ければ安いほどいいです。' => 'Nedan wa yasukereba yasui hodo ii desu.',
    '有名であればあるほど、プライバシーがなくなる。' => 'Yuumei de areba aru hodo, puraibashii ga nakunaru.',
    '高いば高いほど、品質がいいと思います。' => 'Takaiba takai hodo, hinshitsu ga ii to omoimasu.',
    '〜も〜ば〜も: Menyebutkan Beberapa Hal Sejenis' => 'moubaa mo: Menyebutkan Beberapa Hal Sejenis',
    '彼は歌も歌えば、踊りも踊れる。' => 'Kare wa uta mo utaeba, odori mo odoreru.',
    'この店は値段も安ければ、味もいい。' => 'Kono mise wa nedan mo yasukereba, aji mo ii.',
    '学生時代は勉強もすれば、遊びもした。' => 'Gakusei jidai wa benkyou mo sureba, asobi mo shita.',
    '彼女は英語も話せれば、フランス語も話せる。' => 'Kanojo wa eigo mo hanasereba, Furansu go mo hanaseru.',
    'この料理は安いも、おいしいもです。' => 'Kono ryouri wa yasui mo, oishii mo desu.',
    '〜ばこそ: Justru Karena...' => 'ba koso: Justru Karena...',
    'あなたのことを愛していればこそ、厳しく言うのです。' => 'Anata no koto wo aishite ireba koso, kibishiku iu no desu.',
    '苦しい経験があればこそ、今の強さがある。' => 'Kurushii keiken ga areba koso, ima no tsuyosa ga aru.',
    '先生が厳しければこそ、生徒たちは成長できる。' => 'Sensei ga kibishikereba koso, seitotachi wa seichou dekiru.',
    '家族を大切に思えばこそ、無理をしてでも帰るのだ。' => 'Kazoku wo taisetsu ni omoeba koso, muri wo shite de mo kaeru no da.',
    '忙しいこそ、連絡しませんでした。' => 'Isogashii koso, renraku shimasendeshita.',
    '〜ば〜で: Sikap Fleksibel Menghadapi Dua Kemungkinan' => 'baa de: Sikap Fleksibel Menghadapi Dua Kemungkinan',
    'お金があればあったで使ってしまうし、なければないで何とかなる。' => 'Okane ga areba atta de tsukatte shimaushi, nakereba nai de nan to ka naru.',
    '忙しければ忙しいで、それなりに充実している。' => 'Isogashikereba isogashiide, sorenari ni juujitsu shite iru.',
    '子供がいればいたで大変だし、いなければいないで寂しい。' => 'Kodomo ga ireba ita de taihen dashi, inakereba inaide sabishii.',
    '雨が降れば降ったで、家でゆっくりできる。' => 'Ame ga fureba futtade, ie de yukkuri dekiru.',
    'お金があればあるで、大丈夫です。' => 'Okane ga areba aru de, daijoubu desu.',
    '〜ばそれまでだ: Kalau Begitu, Selesai Sudah' => 'ba sore made da: Kalau Begitu, Selesai Sudah',
    'どんなにお金を貯めても、死んでしまえばそれまでだ。' => 'Donna ni okane wo tamete mo, shinde shimaeba sore made da.',
    '信頼を失えばそれまでだ。もう一度取り戻すのは難しい。' => 'Shinrai wo ushinaeba sore made da. mou ichi do torimodosu no wa muzukashii.',
    'せっかくの努力も、諦めてしまえばそれまでだ。' => 'Sekkaku no doryoku mo, akiramete shimaeba sore made da.',
    'この機械は水に濡れればそれまでだから、気をつけてください。' => 'Kono kikai wa mizu ni nurereba sore made dakara, ki wo tsukete kudasai.',
    '失敗するばそれまでだ。' => 'Shippai suruba sore made da.',
