    '何としても、この計画を成功させねばならない。' => 'Nan to shite mo, kono keikaku wo seikou saseneba naranai.',
    '若者は自分の未来のために努力せねばならない。' => 'Wakamono wa jibun no mirai no tame ni doryoku seneba naranai.',
    '規則は守らねばならないものだ。' => 'Kisoku wa mamoraneba naranai mono da.',
