    'Berisiko Menyebabkan Hal Buruk: ～かねない' => 'Berisiko Menyebabkan Hal Buruk: ~kane nai',
    'そのような発言は、誤解を招きかねません。' => 'Sono you na hatsugen wa, gokai wo manekikane masen.',
    '対応が遅れれば、信頼を失いかねない。' => 'Taiou ga okurereba, shinrai wo ushinaikane nai.',
    '無理な計画は、大きな損失につながりかねません。' => 'Muri na keikaku wa, ookina sonshitsu ni tsunagarikane masen.',
    'この問題を放置すれば、深刻な事態になりかねない。' => 'Kono mondai wo houchi sureba, shinkoku na jitai ni narikane nai.',
    'この件は対応いたしかねない場合がございます。' => 'Kono ken wa taiou itashikane nai baai ga gozaimasu.',
    'Menjelaskan Alasan/Kronologi Formal: ～次第です' => 'Menjelaskan Alasan/Kronologi Formal: ~ shidai desu',
    'そのような事情で、今回は参加を見送らせていただいた次第です。' => 'Sono you na jijou de, konkai wa sanka wo miokurasete itadaita shidai desu.',
    '詳細は追ってご連絡申し上げる次第でございます。' => 'Shousai wa otte gorenraku moushiageru shidai de gozaimasu.',
