    'ご請求書につきましては、来週中に発送いたします。' => 'Goseikyuusho ni tsukimashite wa, raishuuchuu ni hassou itashimasu.',
    '本件につきましては、担当部署より回答いたします。' => 'Honken ni tsukimashite wa, tantou busho yori kaitou itashimasu.',
    '明日の天気につきましては、どうなるかな。' => 'Ashita no tenki ni tsukimashite wa, dou naru ka na.',
    'Merendah: Saya Berpendapat Bahwa: ～と存じます' => 'Merendah: Saya Berpendapat Bahwa: ~ to zonjimasu',
    '本件につきましては、慎重な対応が必要かと存じます。' => 'Honken ni tsukimashite wa, shinchou na taiou ga hitsuyou ka to zonjimasu.',
    'ご多忙のところ恐縮ですが、ご協力いただければと存じます。' => 'Gotabou no tokoro kyoushuku desuga, gokyouryoku itadakereba to zonjimasu.',
    '私といたしましては、この案が最適であると存じます。' => 'Watashi to itashimashite wa, kono an ga saiteki de aru to zonjimasu.',
    '皆様にはお変わりなくお過ごしのことと存じます。' => 'Minasama ni wa okawari naku osugoshi no koto to zonjimasu.',
