    'Menyampaikan dengan Hormat: ～申し上げます' => 'Menyampaikan dengan Hormat: ~ moushiagemasu',
    '平素より格別のご高配を賜り、厚く御礼申し上げます。' => 'Heiso yori kakubetsu no gokouhai wo tamawari, atsuku gorei moushiagemasu.',
