    '皆様のご健康とご多幸を祈ってやみません。' => 'Minasama no gokenkou to gotakou wo inotte yamimasen.',
    '彼の才能を私は心から尊敬してやまない。' => 'Kare no sainou wo watashi wa kokoro kara sonkei shite yamanai.',
    '平和な世界の実現を願ってやまない。' => 'Heiwa na sekai no jitsugen wo negatte yamanai.',
    '母は息子の成功を信じてやまなかった。' => 'Haha wa musuko no seikou wo shinjite yamanakatta.',
    'この料理を食べてやまない。' => 'Kono ryouri wo tabete yamanai.',
    'Pola ～に足る (Layak/Pantas untuk...)' => 'Pola ~ ni taru (Layak/Pantas untuk...)',
