    '観光がてら、地元の名物料理を味わった。' => 'Kankougatera, jimoto no meibutsu ryouri wo ajiwatta.',
    '勉強しながらがてら、音楽を聴く。' => 'Benkyou shinagara ga tera, ongaku wo kiku.',
    'Nuansa ～かたわら (Di Sela-sela Kegiatan Utama Jangka Panjang)' => 'Nuansa ~ katawara (Di Sela-sela Kegiatan Utama Jangka Panjang)',
    '彼は会社勤めのかたわら、小説を書いている。' => 'Kare wa kaisha tsutome no katawara, shousetsu wo kaite iru.',
    '彼女は主婦業のかたわら、ボランティア活動を続けている。' => 'Kanojo wa shufugyou no katawara, borantia katsudou wo tsuzukete iru.',
    '教師として働くかたわら、大学院で研究を続けている。' => 'Kyoushi to shite hataraku katawara, daigakuin de kenkyuu wo tsuzukete iru.',
    '農業を営むかたわら、地域の祭りの運営にも携わっている。' => 'Nougyou wo itonamu katawara, chiiki no matsuri no un\'ei ni mo tazusawatte iru.',
    '散歩のかたわら、コンビニに寄った。' => 'Sanpo no katawara, konbini ni yotta.',
    'Nuansa ～かたがた (Sekaligus untuk Tujuan Resmi...)' => 'Nuansa ~ katagata (Sekaligus untuk Tujuan Resmi...)',
    'ご挨拶かたがた、近況をお知らせいたします。' => 'Goaisatsu katagata, kinkyou wo oshirase itashimasu.',
    'お礼かたがた、ご報告申し上げます。' => 'Orei katagata, gohoukoku moushiagemasu.',
    '引っ越しのご挨拶かたがた、お邪魔いたしました。' => 'Hikkoshi no goaisatsu katagata, ojama itashimashita.',
    'お詫びかたがた、事情をご説明いたします。' => 'Owabi katagata, jijou wo gosetsumei itashimasu.',
    '散歩かたがた、買い物をした。' => 'Sanpo katagata, kaimono wo shita.',
    'Nuansa ～にひきかえ (Berbeda Jauh dengan..., Kontras dengan...)' => 'Nuansa ~ ni hikikae (Berbeda Jauh dengan..., Kontras dengan...)',
    '兄が優秀なのにひきかえ、弟は勉強嫌いだ。' => 'Ani ga yuushuu na no ni hikikae, otouto wa benkyou kirai da.',
    '去年の豊作にひきかえ、今年は不作続きだ。' => 'Kyonen no housaku ni hikikae, kotoshi wa fusaku tsuzuki da.',
    '彼女の華やかな成功にひきかえ、私の人生は地味なものだ。' => 'Kanojo no hanayaka na seikou ni hikikae, watashi no jinsei wa jimi na mono da.',
    '口では立派なことを言うのにひきかえ、行動が伴っていない。' => 'Kuchi de wa rippa na koto wo iu no ni hikikae, koudou ga tomonatte inai.',
    '彼は背が高いのにひきかえ、私も背が高い。' => 'Kare wa se ga takai no ni hikikae, watashi mo se ga takai.',
    'Nuansa ～ばこそ (Justru Karena Inilah...)' => 'Nuansa ~ ba koso (Justru Karena Inilah...)',
    '君のことを思えばこそ、厳しく言っているのだ。' => 'Kimi no koto wo omoeba koso, kibishiku itte iru no da.',
    '健康であればこそ、仕事に打ち込める。' => 'Kenkou de areba koso, shigoto ni uchikomeru.',
    '愛していればこそ、別れを選んだ。' => 'Aishite ireba koso, wakare wo eranda.',
    '雨が降ればこそ、試合は中止になった。' => 'Ame ga fureba koso, shiai wa chuushi ni natta.',
    'Nuansa ～もそこそこに (Tergesa-gesa Tanpa Menuntaskan...)' => 'Nuansa ~ mo sokosoko ni (Tergesa-gesa Tanpa Menuntaskan...)',
    '彼は朝食もそこそこに家を飛び出した。' => 'Kare wa choushoku mo sokosoko ni ie wo tobidashita.',
    '挨拶もそこそこに、彼は本題に入った。' => 'Aisatsu mo sokosoko ni, kare wa hondai ni haitta.',
    '彼女は着替えもそこそこに、会社に向かった。' => 'Kanojo wa kigae mo sokosoko ni, kaisha ni mukatta.',
    '荷物を置くのもそこそこに、彼は電話をかけ始めた。' => 'Nimotsu wo oku no mo sokosoko ni, kare wa denwa wo kake hajimeta.',
    '彼はゆっくり食事もそこそこに味わった。' => 'Kare wa yukkuri shokuji mo sokosoko ni ajiwatta.',
    'Nuansa ～ならでは (Khas/Hanya Mungkin Dimiliki oleh...)' => 'Nuansa ~ narade wa (Khas/Hanya Mungkin Dimiliki oleh...)',
    'これは職人ならではの技だ。' => 'Kore wa shokunin narade wa no waza da.',
    'この味は母ならではの手作りの温かさがある。' => 'Kono aji wa haha narade wa no tezukuri no atatakasa ga aru.',
    '京都ならではの風情を楽しんだ。' => 'Kyoto narade wa no fuzei wo tanoshinda.',
    '若さならではの発想が、このプロジェクトを成功させた。' => 'Wakasa narade wa no hassou ga, kono purojekuto wo seikou saseta.',
    'この失敗は彼ならではのミスだ。' => 'Kono shippai wa kare narade wa no misu da.',
    'Nuansa ～てからというもの (Sejak Saat Itu, Terus-menerus...)' => 'Nuansa ~te kara to iu mono (Sejak Saat Itu, Terus-menerus...)',
    '結婚してからというもの、彼はすっかり落ち着いた。' => 'Kekkon shite kara to iu mono, kare wa sukkari ochitsuita.',
    '病気をしてからというもの、健康に気を配るようになった。' => 'Byouki wo shite kara to iu mono, kenkou ni ki wo kubaru you ni natta.',
    '子供が生まれてからというもの、生活が一変した。' => 'Kodomo ga umarete kara to iu mono, seikatsu ga ippen shita.',
    'あの事故を目撃してからというもの、彼は夜も眠れなくなった。' => 'Ano jiko wo mokugeki shite kara to iu mono, kare wa yoru mo nemurenaku natta.',
    '昨日駅に着いてからというもの、電車に乗った。' => 'Kinou eki ni tsuite kara to iu mono, densha ni notta.',
    'Larangan Sastra: ～べからず' => 'Larangan Sastra: ~ bekarazu',
    '初心忘るべからず。' => 'Shoshin wasurubekarazu.',
    '芝生に入るべからず。' => 'Shibafu ni hairubekarazu.',
    'この機密文書は他言すべからず。' => 'Kono kimitsu bunsho wa tagen subekarazu.',
    '図書館内で飲食すべからず。' => 'Toshokannai de inshoku subekarazu.',
    '友達に「今日一緒に遊ぶべからず」と言った。' => 'Tomodachi ni "kyou issho ni asobubekarazu" to itta.',
    '～のみならず: Bukan Hanya... Tetapi Juga (Ragam Tulis)' => '~ nomi narazu: Bukan Hanya... Tetapi Juga (Ragam Tulis)',
    'この政策は国内のみならず、国際社会にも大きな影響を及ぼした。' => 'Kono seisaku wa kokunai nomi narazu, kokusai shakai ni mo ookina eikyou wo oyoboshita.',
    '彼は学者としてのみならず、教育者としても高く評価されている。' => 'Kare wa gakusha to shite nomi narazu, kyouikusha to shite mo takaku hyouka sarete iru.',
    '台風は農作物のみならず、住宅にも甚大な被害をもたらした。' => 'Taifuu wa nousakubutsu nomi narazu, juutaku ni mo jindai na higai wo motarashita.',
    '経済成長は都市部のみならず地方にも波及している。' => 'Keizai seichou wa toshi bu nomi narazu chihou ni mo hakyuu shite iru.',
    '友達との会話で「彼は優しいのみならず、面白いっす」と言った。' => 'Tomodachi to no kaiwa de "kare wa yasashii nomi narazu, omoshiroissu" to itta.',
    '～たる者: Sebagai Seseorang yang Berstatus/Berkedudukan' => '~ taru mono: Sebagai Seseorang yang Berstatus/Berkedudukan',
    '教師たる者、常に生徒の模範であるべきだ。' => 'Kyoushi taru mono, tsune ni seito no mohan de arubekida.',
    'リーダーたる者は、責任を持って決断しなければならない。' => 'Riidaa taru mono wa, sekinin wo motte ketsudan shinakereba naranai.',
    '医者たる者、患者の命を第一に考えるべきである。' => 'Isha taru mono, kanja no inochi wo daiichi ni kangaerubekide aru.',
    '政治家たる者が私利私欲に走ってはならない。' => 'Seijika taru mono ga shiri shiyoku ni hashitte wa naranai.',
    '忙しいたる者、休むべきだ。' => 'Isogashiitaru mono, yasumubekida.',
    '～と相まって: Berpadu dengan Faktor Lain' => '~ to aimatte: Berpadu dengan Faktor Lain',
    '円安は原油価格の高騰と相まって、物価上昇に拍車をかけた。' => 'En\'yasu wa gen\'yu kakaku no koutou to aimatte, bukka joushou ni hakusha wo kaketa.',
    '美しい景観は温暖な気候と相まって、多くの観光客を引き寄せている。' => 'Utsukushii keikan wa ondan na kikou to aimatte, ooku no kankou kyaku wo hikiyosete iru.',
    '彼の才能は努力と相まって、大きな成功を収めた。' => 'Kare no sainou wa doryoku to aimatte, ookina seikou wo osameta.',
    '少子化は高齢化と相まって、労働力不足を深刻化させている。' => 'Shoushika wa koureika to aimatte, roudouryoku fusoku wo shinkokuka sasete iru.',
    '天気が悪いと相まって、今日は出かけたくない。' => 'Tenki ga warui to aimatte, kyou wa dekaketaku nai.',
    '～んがため（に）: Demi Mencapai Tujuan (Ragam Sastra)' => '~ n ga tame (ni): Demi Mencapai Tujuan (Ragam Sastra)',
    '彼は家族を守らんがために、危険を顧みず行動した。' => 'Kare wa kazoku wo mamoranga tame ni, kiken wo kaerimizu koudou shita.',
    '目的を達成せんがために、彼女はあらゆる手段を尽くした。' => 'Mokuteki wo tassei sen ga tame ni, kanojo wa arayuru shudan wo tsukushita.',
    '生きんがための戦いだった。' => 'Ikinga tame no tatakai datta.',
    '真実を明らかにせんがため、記者は取材を続けた。' => 'Shinjitsu wo akiraka ni sen ga tame, kisha wa shuzai wo tsuzuketa.',
    '友達に「買い物に行かんがために出かけた」と言った。' => 'Tomodachi ni "kaimono ni ikanga tame ni dekaketa" to itta.',
    '～べく: Demi Melakukan Sesuatu (Ragam Formal dari ため に)' => '~ beku: Demi Melakukan Sesuatu (Ragam Formal dari tame ni)',
    '課題を解決すべく、チーム全員で議論を重ねた。' => 'Kadai wo kaiketsu subeku, chiimu zen\'in de giron wo kasaneta.',
    '新製品を開発すべく、研究チームが結成された。' => 'Shinseihin wo kaihatsu subeku, kenkyuu chiimu ga kessei sareta.',
    '状況を打開すべく、政府は緊急対策を発表した。' => 'Joukyou wo dakai subeku, seifu wa kinkyuu taisaku wo happyou shita.',
    '真相を究明すべく、調査委員会が設置された。' => 'Shinsou wo kyuumei subeku, chousa iin kai ga setchi sareta.',
    '映画を見るべく友達と会った。' => 'Eiga wo mirubeku tomodachi to atta.',
    '～こととて: Karena Merupakan Hal yang... (Ragam Sastra Permintaan Maaf)' => '~ koto tote: Karena Merupakan Hal yang... (Ragam Sastra Permintaan Maaf)',
    '不慣れなこととて、失礼がありましたらお許しください。' => 'Funare na koto tote, shitsurei ga arimashitara oyurushi kudasai.',
    '急な事のこととて、十分な準備ができませんでした。' => 'Kyuu na koto no koto tote, juubun na junbi ga dekimasendeshita.',
    '世間知らずのこととて、とんだご迷惑をおかけしました。' => 'Seken shirazu no koto tote, tonda gomeiwaku wo okake shimashita.',
    '初めてのこととて、うまく対応できませんでした。' => 'Hajimete no koto tote, umaku taiou dekimasendeshita.',
    '友達に「慣れてないこととて、ごめんね」と言った。' => 'Tomodachi ni "naretenai koto tote, gomen ne" to itta.',
    '～に至っては: Kalau Sampai pada Hal Itu (Kasus Ekstrem)' => '~ ni itatte wa: Kalau Sampai pada Hal Itu (Kasus Ekstrem)',
    '若者の活字離れは深刻で、中には一年に一冊も本を読まない者に至っては珍しくない。' => 'Wakamono no katsuji hanare wa shinkoku de, naka ni wa ichi nen ni ichisatsu mo hon wo yomanai mono ni itatte wa mezurashiku nai.',
    '三男に至っては、大学進学すら諦めてしまった。' => 'Sannan ni itatte wa, daigaku shingaku sura akiramete shimatta.',
    '売り上げは全体的に落ち込んでいるが、地方店舗に至っては半減している。' => 'Uriage wa zentaiteki ni ochikonde iruga, chihou tenpo ni itatte wa hangen shite iru.',
    '批判の声は日増しに強まり、一部の株主に至っては辞任を求めている。' => 'Hihan no koe wa himashi ni tsuyomari, ichibu no kabunushi ni itatte wa jinin wo motomete iru.',
    '交渉は決裂に至っては、両者は退席した。' => 'Koushou wa ketsuretsu ni itatte wa, ryousha wa taiseki shita.',
    '～ずにはおかない: Pasti Akan Terjadi (Efek yang Tak Terelakkan)' => '~ zu ni wa okanai: Pasti Akan Terjadi (Efek yang Tak Terelakkan)',
    'この映画は観客の心を揺さぶらずにはおかないだろう。' => 'Kono eiga wa kankyaku no kokoro wo yusaburazu ni wa okanaidarou.',
    '彼の演説は聴衆を感動させずにはおかなかった。' => 'Kare no enzetsu wa choushuu wo kandou sasezu ni wa okanakatta.',
    '真相が明らかになれば、世間を驚かせずにはおかないだろう。' => 'Shinsou ga akiraka ni nareba, seken wo odorokasezu ni wa okanaidarou.',
    'その残酷な描写は読者に衝撃を与えずにはおかない。' => 'Sono zankoku na byousha wa dokusha ni shougeki wo ataezu ni wa okanai.',
    '明日雨が降らずにはおかない。' => 'Ashita ame ga furazu ni wa okanai.',
    '～てやまない: Tak Henti-hentinya (Perasaan yang Tulus)' => '~ te yamanai: Tak Henti-hentinya (Perasaan yang Tulus)',
    'ご健康とご多幸を祈ってやみません。' => 'Gokenkou to gotakou wo inotte yamimasen.',
    '彼の功績は多くの人々に尊敬されてやまない。' => 'Kare no kouseki wa ooku no hitobito ni sonkei sarete yamanai.',
    '一日も早い復興を願ってやみません。' => 'Ichi nichi mo hayai fukkou wo negatte yamimasen.',
    '彼女は生涯、音楽を愛してやまなかった。' => 'Kanojo wa shougai, ongaku wo aishite yamanakatta.',
    '彼は食べてやまない。' => 'Kare wa tabete yamanai.',
    '～なくして（は）: Tanpa... (Mustahil Terjadi)' => '~ nakushite (ha): Tanpa... (Mustahil Terjadi)',
    '努力なくして成功はあり得ない。' => 'Doryoku naku shite seikou wa ari enai.',
    '国民の理解なくしては、この改革は実現できない。' => 'Kokumin no rikai naku shite wa, kono kaikaku wa jitsugen dekinai.',
    '信頼関係なくして、良いチームワークは生まれない。' => 'Shinrai kankei naku shite, yoi chiimuwaaku wa umarenai.',
    '十分な準備なくして、大きな挑戦に立ち向かうことはできない。' => 'Juubun na junbi naku shite, ookina chousen ni tachimukau koto wa dekinai.',
    '頑張るなくして成功しない。' => 'Ganbaru nakushite seikou shinai.',
    '～きらいがある: Cenderung Memiliki Kecenderungan yang Kurang Baik' => '~ kirai ga aru: Cenderung Memiliki Kecenderungan yang Kurang Baik',
    'この制度は形式主義に陥るきらいがある。' => 'Kono seido wa keishiki shugi ni ochiiru kirai ga aru.',
    '若い世代は活字を軽視するきらいがある。' => 'Wakai sedai wa katsuji wo keishi suru kirai ga aru.',
    '彼女の意見は極端に走るきらいがある。' => 'Kanojo no iken wa kyokutan ni hashiru kirai ga aru.',
    '彼女は歌が上手なきらいがある。' => 'Kanojo wa uta ga jouzu na kirai ga aru.',
    '～にかたくない: Mudah Dibayangkan/Dipahami Tanpa Kesulitan' => '~ ni kataku nai: Mudah Dibayangkan/Dipahami Tanpa Kesulitan',
    '彼の悲しみは想像にかたくない。' => 'Kare no kanashimi wa souzou ni kataku nai.',
    '被災地の苦労は察するにかたくない。' => 'Hisai chi no kurou wa sassuru ni kataku nai.',
    'ご遺族のお気持ちは察するにかたくない。' => 'Goizoku no okimochi wa sassuru ni kataku nai.',
    '彼女がどれほど努力したかは想像にかたくない。' => 'Kanojo ga dore hodo doryoku shita ka wa souzou ni kataku nai.',
    'このラーメンは食べるにかたくない。' => 'Kono raamen wa taberu ni kataku nai.',
    '～ものとする: Ditetapkan/Diberlakukan Sebagai (Bahasa Hukum)' => '~ mono to suru: Ditetapkan/Diberlakukan Sebagai (Bahasa Hukum)',
    '会員は年会費を毎年4月末までに納付するものとする。' => 'Kaiin wa nen kaihi wo maitoshi 4 gatsumatsu made ni noufu suru mono to suru.',
    '本契約の有効期間は1年とし、以降は自動的に更新されるものとする。' => 'Honkeiyaku no yuukou kikan wa 1 nen to shi, ikou wa jidouteki ni koushin sareru mono to suru.',
    '未成年者が申し込む場合は、保護者の同意を得るものとする。' => 'Miseinensha ga moushikomu baai wa, hogosha no doui wo eru mono to suru.',
    '本契約に関する紛争は、甲乙協議の上解決するものとする。' => 'Honkeiyaku ni kansuru funsou wa, kouotsu kyougi no ue kaiketsu suru mono to suru.',
    '明日は雨が降るものとする。' => 'Ashita wa ame ga furu mono to suru.',
    '～に処する: Dijatuhi/Dikenai Hukuman (Bahasa Hukum)' => '~ ni shosuru: Dijatuhi/Dikenai Hukuman (Bahasa Hukum)',
    '被告人を懲役5年に処する。' => 'Hikokunin wo choueki 5 nen ni shosuru.',
    '違反者は50万円以下の罰金に処せられる。' => 'Ihansha wa 50 man en ika no bakkin ni shoserareru.',
    '裁判所は彼を禁錮2年に処した。' => 'Saibansho wa kare wo kinko 2 nen ni shoshita.',
    '悪質な脱税行為は重い罰金刑に処せられることがある。' => 'Akushitsu na datsuzei koui wa omoi bakkin kei ni shoserareru koto ga aru.',
    '友達に「遅刻したら罰金に処するよ！」と冗談を言った。' => 'Tomodachi ni "chikoku shitara bakkin ni shosuru yo!" to joudan wo itta.',
    '～を禁ずる（禁じる）: Melarang Secara Resmi' => '~ wo kinzuru (kinjiru): Melarang Secara Resmi',
    '館内での喫煙を禁ずる。' => 'Kannai de no kitsuen wo kinzuru.',
    '無断駐車を固く禁じます。' => 'Mudan chuusha wo kataku kinjimasu.',
    '法律により、未成年者への酒類の販売を禁じている。' => 'Houritsu ni yori, miseinensha e no shurui no hanbai wo kinjite iru.',
    'この区域への立ち入りを禁ずる。' => 'Kono kuiki e no tachiiri wo kinzuru.',
    'お母さんは子供に「ゲームを禁ずる！」と言った。' => 'Ohahasan wa kodomo ni "geemu wo kinzuru!" to itta.',
    '～の限りでない: Tidak Berlaku dalam Hal Ini (Klausul Pengecualian)' => '~ no kagiri de nai: Tidak Berlaku dalam Hal Ini (Klausul Pengecualian)',
    '会員は退会届を提出しなければならない。ただし、やむを得ない事情がある場合は、この限りでない。' => 'Kaiin wa taikai todoke wo teishutsu shinakereba naranai. tadashi, yamu wo enai jijou ga aru baai wa, kono kagiri de nai.',
    '本規則は全職員に適用する。ただし、非常勤職員はこの限りでない。' => 'Honkisoku wa zenshokuin ni tekiyou suru. tadashi, hijoukin shokuin wa kono kagiri de nai.',
    '商品は返品を受け付けない。ただし、不良品の場合はこの限りでない。' => 'Shouhin wa henpin wo uketsukenai. tadashi, furyouhin no baai wa kono kagiri de nai.',
    '会議は原則として月1回開催する。ただし、緊急の議題がある場合はこの限りでない。' => 'Kaigi wa gensoku to shite tsuki 1 kai kaisai suru. tadashi, kinkyuu no gidai ga aru baai wa kono kagiri de nai.',
    '宿題は今日中に出さなきゃいけない、でもこの限りでない。' => 'Shukudai wa kyouchuu ni dasanakya ikenai, de mo kono kagiri de nai.',
    '～をもって: Dengan/Melalui (Sarana atau Batas Waktu Resmi)' => '~ wo motte: Dengan/Melalui (Sarana atau Batas Waktu Resmi)',
    '本日をもちまして、閉店とさせていただきます。' => 'Honjitsu wo mochimashite, heiten to sasete itadakimasu.',
    '書面をもって通知するものとする。' => 'Shomen wo motte tsuuchi suru mono to suru.',
    '彼の長年の功績をもって、表彰することとなった。' => 'Kare no naganen no kouseki wo motte, hyoushou suru koto to natta.',
    '本日の会議をもって、今年度の議事はすべて終了した。' => 'Honjitsu no kaigi wo motte, konnendo no giji wa subete shuuryou shita.',
    '明日をもって友達に会う。' => 'Ashita wo motte tomodachi ni au.',
    '～に鑑みて: Mengingat/Menimbang (Alasan Formal)' => '~ ni kangamite: Mengingat/Menimbang (Alasan Formal)',
    '昨今の経済情勢に鑑み、当社は経費削減を実施することとした。' => 'Sakkon no keizai jousei ni kangami, tousha wa keihi sakugen wo jisshi suru koto to shita.',
    '過去の事故事例に鑑みて、安全対策を強化する。' => 'Kako no jiko jirei ni kangamite, anzen taisaku wo kyouka suru.',
    '現状に鑑み、規則の見直しが必要である。' => 'Genjou ni kangami, kisoku no minaoshi ga hitsuyou de aru.',
    '国際情勢の変化に鑑みて、政府は新たな方針を発表した。' => 'Kokusai jousei no henka ni kangamite, seifu wa arata na houshin wo happyou shita.',
    '天気に鑑みて、傘を持っていく。' => 'Tenki ni kangamite, kasa wo motte iku.',
    '～と称する: Menyebut/Mengaku Diri Sebagai (Register Resmi/Curiga)' => '~ to shousuru: Menyebut/Mengaku Diri Sebagai (Register Resmi/Curiga)',
    '詐欺グループは「銀行員」と称して高齢者に電話をかけていた。' => 'Sagi guruupu wa "ginkouin" to shoushite koureisha ni denwa wo kakete ita.',
    '本製品は「天然由来」と称しているが、実際には化学成分が含まれている。' => 'Honseihin wa "tennen yurai" to shoushite iruga, jissai ni wa kagaku seibun ga fukumarete iru.',
    '彼は投資顧問と称して多額の金銭をだまし取った。' => 'Kare wa toushi komon to shoushite tagaku no kinsen wo damashitotta.',
    '当団体はボランティア団体と称しているが、実態は営利目的である。' => 'Toudantai wa borantia dantai to shoushite iruga, jittai wa eiri mokuteki de aru.',
    '友達に「僕は田中と称します」と自己紹介した。' => 'Tomodachi ni "boku wa Tanaka to shoushimasu" to jiko shoukai shita.',
    '～に足る／に足りない: Layak/Tidak Layak (Kelayakan Formal)' => '~ ni taru/ni tarinai: Layak/Tidak Layak (Kelayakan Formal)',
    'この証拠は彼の無実を証明するに足るものではない。' => 'Kono shouko wa kare no mujitsu wo shoumei suru ni taru mono de wa nai.',
    '彼女の功績は歴史に名を残すに足るものだ。' => 'Kanojo no kouseki wa rekishi ni na wo nokosu ni taru mono da.',
    'その主張は反論するに足りない。' => 'Sono shuchou wa hanron suru ni tarinai.',
    'このラーメンは美味しいに足る。' => 'Kono raamen wa oishii ni taru.',
    '～を余儀なくされる: Terpaksa Mengalami (Akibat Keadaan di Luar Kendali)' => '~ wo yogi naku sareru: Terpaksa Mengalami (Akibat Keadaan di Luar Kendali)',
    '大雨の影響で、多くの住民が避難を余儀なくされた。' => 'Ooame no eikyou de, ooku no juumin ga hinan wo yogi naku sareta.',
    '経営不振により、同社は事業の縮小を余儀なくされた。' => 'Keiei fushin ni yori, dousha wa jigyou no shukushou wo yogi naku sareta.',
    '感染拡大の影響で、イベントは中止を余儀なくされた。' => 'Kansen kakudai no eikyou de, ibento wa chuushi wo yogi naku sareta.',
    '眠かったので、早寝を余儀なくされた。' => 'Nemukatta no de, hayane wo yogi naku sareta.',
    '～いかんによらず／いかんを問わず: Tanpa Memandang Bagaimanapun Keadaannya' => '~ ikan ni yorazu/ikan wo towazu: Tanpa Memandang Bagaimanapun Keadaannya',
    '理由のいかんによらず、遅刻は減点の対象となる。' => 'Riyuu no ikan ni yorazu, chikoku wa genten no taishou to naru.',
