    'この理論は科学的根拠たり得るか、議論の余地がある。' => 'Kono riron wa kagakuteki konkyo tari uru ka, giron no yochi ga aru.',
    '彼は次期リーダーたり得る人物だと評価されている。' => 'Kare wa jiki riidaa tari eru jinbutsu da to hyouka sarete iru.',
    '単なる噂は証拠たり得ない。' => 'Tannaru uwasa wa shouko tari enai.',
    'この国は真の民主主義国家たり得るかが問われている。' => 'Kono kuni wa shin no minshu shugi kokka tari uru ka ga towarete iru.',
