    '東京へ行くなら、新幹線が便利です。' => 'Tokyo e ikunara, shinkansen ga benri desu.',
    '辞書が必要なら、私のを貸します。' => 'Jisho ga hitsuyou nara, watashi no wo kashimasu.',
    '京都なら、桜がきれいな場所をたくさん知っています。' => 'Kyoto nara, sakura ga kirei na basho wo takusan shitte imasu.',
    '田中さんが忙しいなら、明日にしましょう。' => 'Tanakasan ga isogashiinara, ashita ni shimashou.',
    'A: 東京へ行きます。 B: 東京へ行ったら、新幹線が便利です。' => 'A: Tokyo e ikimasu. B: Tokyo e ittara, shinkansen ga benri desu.',
    'Struktur Saran Kondisional dengan たらどうですか' => 'Struktur Saran Kondisional dengan tara dou desu ka',
    '疲れたら、少し休んだらどうですか。' => 'Tsukaretara, sukoshi yasundara dou desu ka.',
