    'わからないところがあったら、先生に聞いたらどうですか。' => 'Wakaranai tokoro ga attara, sensei ni kiitara dou desu ka.',
    'そんなに心配なら、電話したらどうですか。' => 'Sonna ni shinpai nara, denwa shitara dou desu ka.',
    '少し休んだどうですか。' => 'Sukoshi yasunda dou desu ka.',
    'Struktur Klausa Kondisional Negatif なければ untuk Kewajiban' => 'Struktur Klausa Kondisional Negatif nakereba untuk Kewajiban',
    '明日までに宿題を出さなければ、先生に叱られます。' => 'Ashita made ni shukudai wo dasanakereba, sensei ni shikararemasu.',
    '薬を飲まなければ、熱が下がりません。' => 'Kusuri wo nomanakereba, netsu ga sagarimasen.',
    'パスポートを見せなければ、飛行機に乗れません。' => 'Pasupooto wo misenakereba, hikou ki ni noremasen.',
    '予約しなければ、そのレストランには入れません。' => 'Yoyaku shinakereba, sono resutoran ni wa iremasen.',
    '宿題を出さない、先生に叱られます。' => 'Shukudai wo dasanai, sensei ni shikararemasu.',
    'Struktur Dasar Kalimat Sebab-Akibat dengan から' => 'Struktur Dasar Kalimat Sebab-Akibat dengan kara',
    '今日は雨だから、傘を持って行きます。' => 'Kyou wa ame dakara, kasa wo motte ikimasu.',
    'このレストランはおいしいから、いつも混んでいます。' => 'Kono resutoran wa oishiikara, itsu mo konde imasu.',
    '時間がないから、急ぎましょう。' => 'Jikan ga naikara, isogimashou.',
    '明日テストがあるから、今夜勉強します。' => 'Ashita tesuto ga arukara, kon\'ya benkyou shimasu.',
    '傘を持って行きますから、今日は雨です。' => 'Kasa wo motte ikimasukara, kyou wa ame desu.',
    'Struktur Kalimat Sebab-Akibat Formal dengan ので' => 'Struktur Kalimat Sebab-Akibat Formal dengan no de',
    '明日は忙しいので、早く帰ります。' => 'Ashita wa isogashii no de, hayaku kaerimasu.',
    '今日は休みなので、どこかへ出かけましょう。' => 'Kyou wa yasumi na no de, doko ka e dekakemashou.',
    '電車が遅れたので、会議に遅刻しました。' => 'Densha ga okureta no de, kaigi ni chikoku shimashita.',
    '体調が悪いので、今日は休ませてください。' => 'Taichou ga warui no de, kyou wa yasumasete kudasai.',
    '今日は休みので、どこかへ出かけましょう。' => 'Kyou wa yasumi no de, doko ka e dekakemashou.',
    'Struktur Akibat Lebih Dulu dengan から di Akhir Kalimat' => 'Struktur Akibat Lebih Dulu dengan kara di Akhir Kalimat',
    '今日は行きません。ちょっと疲れているから。' => 'Kyou wa ikimasen. chotto tsukarete irukara.',
    '心配しないでください。もう大丈夫だから。' => 'Shinpai shinaide kudasai. mou daijoubu dakara.',
    '早く寝たほうがいいよ。明日早いから。' => 'Hayaku neta hou ga ii yo. ashita hayaikara.',
    'この店にしよう。安くておいしいから。' => 'Kono mise ni shiyou. yasukute oishiikara.',
