    'Struktur Pertanyaan Sebab dengan どうして/なぜ dan Jawaban から' => 'Struktur Pertanyaan Sebab dengan dou shite/naze dan Jawaban kara',
    'どうして学校を休んだんですか。風邪をひいたからです。' => 'Dou shite gakkou wo yasunda n desu ka. kaze wo hiitakara desu.',
    'なぜ日本語を勉強しているんですか。日本のアニメが好きだからです。' => 'Naze Nihon go wo benkyou shite iru n desu ka. Nihon no anime ga suki dakara desu.',
    'どうして遅れたんですか。電車が止まったからです。' => 'Dou shite okureta n desu ka. densha ga tomattakara desu.',
