    '大雨のため、傘を持って行きましょう。' => 'Ooame no tame, kasa wo motte ikimashou.',
    'Struktur Kutipan Langsung dengan と言う' => 'Struktur Kutipan Langsung dengan to yuu',
    '田中さんは「明日は休みます」と言いました。' => 'Tanakasan wa "ashita wa yasumimasu" to iimashita.',
