    '彼は「もう帰ります」と言いました。' => 'Kare wa "mou kaerimasu" to iimashita.',
    '母は「気をつけてね」と言いました。' => 'Haha wa "ki wo tsukete ne" to iimashita.',
    '田中さんは明日は休みますと言いました。' => 'Tanakasan wa ashita wa yasumimasu to iimashita.',
    'Struktur Opini dengan と思う' => 'Struktur Opini dengan to omou',
    '明日は雨が降ると思います。' => 'Ashita wa ame ga furu to omoimasu.',
