    'この問題は難しいと思います。' => 'Kono mondai wa muzukashii to omoimasu.',
    '明日は雨が降りますと思います。' => 'Ashita wa ame ga furimasu to omoimasu.',
    'Struktur Kutipan Pertanyaan Tertanam dengan かどうか' => 'Struktur Kutipan Pertanyaan Tertanam dengan ka dou ka',
    '彼が来るかどうかわかりません。' => 'Kare ga kuru ka dou ka wakarimasen.',
    'この答えが正しいかどうか教えてください。' => 'Kono kotae ga tadashii ka dou ka oshiete kudasai.',
