    '静かだった町が昔は今はにぎやかになりました。' => 'Shizuka datta machi ga mukashi wa ima wa nigiyaka ni narimashita.',
    'Struktur Klausa Relatif dengan Subjek Berbeda Ditandai が' => 'Struktur Klausa Relatif dengan Subjek Berbeda Ditandai ga',
