    '母が好きな花はバラです。' => 'Haha ga suki na hana wa bara desu.',
    '友達が住んでいる町は静かです。' => 'Tomodachi ga sunde iru machi wa shizuka desu.',
    '先生が書いた本は難しいです。' => 'Sensei ga kaita hon wa muzukashii desu.',
    '私は作ったケーキはとても甘いです。' => 'Watashi wa tsukutta keeki wa totemo amai desu.',
    'Struktur Urutan Aksi dengan てから' => 'Struktur Urutan Aksi dengan te kara',
    '手を洗ってから、ご飯を食べます。' => 'Te wo aratte kara, gohan wo tabemasu.',
    '宿題をしてから、テレビを見ます。' => 'Shukudai wo shite kara, terebi wo mimasu.',
    'シャワーを浴びてから、寝ます。' => 'Shawaa wo abite kara, nemasu.',
    '日本に来てから、日本語を勉強し始めました。' => 'Nihon ni kite kara, Nihon go wo benkyou shi hajimemashita.',
    'ご飯を食べてから、手を洗います。' => 'Gohan wo tabete kara, te wo araimasu.',
    'Struktur Urutan Aksi dengan た後で' => 'Struktur Urutan Aksi dengan ta ato de',
    '食事をした後で、薬を飲みます。' => 'Shokuji wo shita ato de, kusuri wo nomimasu.',
