    '会議の後で、資料をまとめます。' => 'Kaigi no ato de, shiryou wo matomemasu.',
    '食事する後で、薬を飲みます。' => 'Shokuji suru ato de, kusuri wo nomimasu.',
    'Struktur Urutan Terbalik dengan 前に' => 'Struktur Urutan Terbalik dengan mae ni',
    '出かける前に、天気を確認します。' => 'Dekakeru mae ni, tenki wo kakunin shimasu.',
    '日本へ行く前に、少し日本語を勉強しました。' => 'Nihon e iku mae ni, sukoshi Nihon go wo benkyou shimashita.',
    '食べる前に、手を洗ってください。' => 'Taberu mae ni, te wo aratte kudasai.',
    'Struktur Rangkaian Aksi dengan Bentuk Te Berulang' => 'Struktur Rangkaian Aksi dengan Bentuk Te Berulang',
    '朝起きて、顔を洗って、朝ご飯を食べます。' => 'Asa okite, kao wo aratte, asagohan wo tabemasu.',
    '家に帰って、シャワーを浴びて、すぐ寝ました。' => 'Ie ni kaette, shawaa wo abite, sugu nemashita.',
    '図書館へ行って、本を借りて、家で読みました。' => 'Toshokan e itte, hon wo karite, ie de yomimashita.',
    '野菜を切って、鍋に入れて、煮ます。' => 'Yasai wo kitte, nabe ni irete, nimasu.',
    '朝起きます、顔を洗います、朝ご飯を食べます。' => 'Asa okimasu, kao wo araimasu, asagohan wo tabemasu.',
    'Struktur Urutan Aksi Langsung dengan てすぐに' => 'Struktur Urutan Aksi Langsung dengan te sugu ni',
    '家に着いてすぐに、雨が降り始めました。' => 'Ie ni tsuite sugu ni, ame ga furi hajimemashita.',
    '起きてすぐに、メールをチェックします。' => 'Okite sugu ni, meeru wo chekku shimasu.',
