    '電話を切ってすぐに、彼から連絡が来ました。' => 'Denwa wo kitte sugu ni, kare kara renraku ga kimashita.',
    '家に着いたすぐに、雨が降り始めました。' => 'Ie ni tsuita sugu ni, ame ga furi hajimemashita.',
    'Perbedaan Struktur から、ので、dan ため(に) dalam Menyusun Alasan' => 'Perbedaan Struktur kara, no de, dan tame (ni) dalam Menyusun Alasan',
    '雨が降っているので、試合は中止になりました。' => 'Ame ga futte iru no de, shiai wa chuushi ni narimashita.',
    '道が混んでいるから、早く出た方がいいよ。' => 'Michi ga konde irukara, hayaku deta hou ga ii yo.',
    '台風が接近しているため、電車が運休しております。' => 'Taifuu ga sekkin shite iru tame, densha ga unkyuu shite orimasu.',
    '経験不足のため、今回のプロジェクトは彼に任せられない。' => 'Keiken fusoku no tame, konkai no purojekuto wa kare ni makaserarenai.',
    '時間がないため、急いでください。' => 'Jikan ga nai tame, isoide kudasai.',
    'Struktur Simpulan Alasan dengan わけだ' => 'Struktur Simpulan Alasan dengan wake da',
    '彼は10年間フランスに住んでいた。だからフランス語が上手なわけだ。' => 'Kare wa 10 nenkan Furansu ni sunde ita. dakara Furansu go ga jouzu na wake da.',
    '今日は祝日だ。道理で会社が休みなわけだ。' => 'Kyou wa shukujitsu da. douri de kaisha ga yasumi na wake da.',
    '彼女は医者の娘だ。それで医学に詳しいわけだ。' => 'Kanojo wa isha no musume da. sore de igaku ni kuwashii wake da.',
    'この会社は給料もいいし休みも多い。人気があるわけだ。' => 'Kono kaisha wa kyuuryou mo iishi yasumi mo ooi. ninki ga aru wake da.',
