    'Menyusun Dua Alasan Sekaligus dengan ～し、～し' => 'Menyusun Dua Alasan Sekaligus dengan ~ shi,~ shi',
    'この店は安いし、味もいいし、いつも混んでいる。' => 'Kono mise wa yasuishi, aji mo iishi, itsu mo konde iru.',
    '今日は疲れたし、雨も降っているし、家でゆっくりしよう。' => 'Kyou wa tsukaretashi, ame mo futte irushi, ie de yukkuri shiyou.',
    '彼は頭もいいし、努力家だし、きっと成功するだろう。' => 'Kare wa atama mo iishi, doryokuka dashi, kitto seikou surudarou.',
    'このアパートは駅から近いし、家賃も安いし、人気がある。' => 'Kono apaato wa eki kara chikaishi, yachin mo yasuishi, ninki ga aru.',
    '安いし、この店に入りましょう。' => 'Yasuishi, kono mise ni hairimashou.',
    'Alasan Emosional dengan ものだから／もので' => 'Alasan Emosional dengan mono dakara/mono de',
    '電車が遅れたものですから、遅刻してしまいました。' => 'Densha ga okureta mono desukara, chikoku shite shimaimashita.',
    '急に用事ができたもので、参加できませんでした。' => 'Kyuu ni youji ga dekita mono de, sanka dekimasendeshita.',
    '子供がまだ小さいものだから、なかなか外出できないんです。' => 'Kodomo ga mada chiisai mono dakara, nakanaka gaishutsu dekinai n desu.',
    '初めての場所だったものですから、道に迷ってしまいました。' => 'Hajimete no basho datta mono desukara, michi ni mayotte shimaimashita.',
    '疲れたものだから、明日も頑張りましょう。' => 'Tsukareta mono dakara, ashita mo ganbarimashou.',
    'Struktur Alasan Bernuansa dengan せいで dan おかげで' => 'Struktur Alasan Bernuansa dengan sei de dan okage de',
    '道路工事のせいで、渋滞がひどくなった。' => 'Douro kouji no sei de, juutai ga hidoku natta.',
    '先生のおかげで、試験に合格することができました。' => 'Sensei no okage de, shiken ni goukaku suru koto ga dekimashita.',
    '彼が遅刻したせいで、会議が始められなかった。' => 'Kare ga chikoku shita sei de, kaigi ga hajimerarenakatta.',
    '天気が良かったおかげで、旅行がとても楽しかった。' => 'Tenki ga yokatta okage de, ryokou ga totemo tanoshikatta.',
    '両親が支えてくれたせいで、無事に卒業できました。' => 'Ryoushin ga sasaete kureta sei de, buji ni sotsugyou dekimashita.',
    'Struktur ば～ほど untuk Pengandaian Bertingkat' => 'Strukturba~ hodo untuk Pengandaian Bertingkat',
    'この本は読めば読むほど面白くなる。' => 'Kono hon wa yomeba yomu hodo omoshiroku naru.',
    '練習すればするほど上手になります。' => 'Renshuu sureba suru hodo jouzu ni narimasu.',
