    '勉強すればほど、成績が上がる。' => 'Benkyou sureba hodo, seiseki ga agaru.',
    'Menggabungkan たら dengan Penemuan Tak Terduga (発見のたら)' => 'Menggabungkan tara dengan Penemuan Tak Terduga (hakken no tara)',
    '家に帰ったら、誰もいなかった。' => 'Ie ni kaettara, dare mo inakatta.',
    '窓を開けたら、雪が降っていた。' => 'Mado wo aketara, yuki ga futte ita.',
    '財布を開けたら、お金が入っていなかったので驚いた。' => 'Saifu wo aketara, okane ga haitte inakatta no de odoroita.',
    '薬を飲んだら、すぐ熱が下がった。' => 'Kusuri wo nondara, sugu netsu ga sagatta.',
    '家に帰ったら、必ず勉強してください。' => 'Ie ni kaettara, kanarazu benkyou shite kudasai.',
    'なら sebagai Pengandaian Berbasis Topik dan Saran' => 'Nara sebagai Pengandaian Berbasis Topik dan Saran',
    '京都に行くなら、桜が咲く春がいいですよ。' => 'Kyoto ni ikunara, sakura ga saku haru ga ii desu yo.',
    'A：頭が痛いんです。B：頭が痛いなら、早く休んだ方がいいですよ。' => 'A: atama ga itai n desu. B: atama ga itainara, hayaku yasunda hou ga ii desu yo.',
    '車を買うなら、燃費のいいものを選んだ方がいい。' => 'Kuruma wo kaunara, nenpi no ii mono wo eranda hou ga ii.',
    '安いスマホなら、この店がおすすめです。' => 'Yasui sumaho nara, kono mise ga osusume desu.',
    '雨が降るなら、傘を忘れて出かけた。' => 'Ame ga furunara, kasa wo wasurete dekaketa.',
    'Menggabungkan たとえ～ても sebagai Pengandaian Konsesif' => 'Menggabungkan tatoe~te mo sebagai Pengandaian Konsesif',
    'たとえ失敗しても、最後まで挑戦し続けるつもりです。' => 'Tatoe shippai shite mo, saigo made chousen shi tsuzukeru tsumori desu.',
    'たとえ雨が降っても、試合は予定通り行われます。' => 'Tatoe ame ga futte mo, shiai wa yotei toori okonawaremasu.',
    'たとえどんなに忙しくても、家族との時間は大切にしたい。' => 'Tatoe donna ni isogashikute mo, kazoku to no jikan wa taisetsu ni shitai.',
    'たとえ高くても、質のいい物を買いたい。' => 'Tatoe takakute mo, shitsu no ii mono wo kaitai.',
    'たとえ疲れたので、休みたい。' => 'Tatoe tsukareta no de, yasumitai.',
    'Pengandaian Berlapis dengan もし～としたら' => 'Pengandaian Berlapis dengan moshi~ to shitara',
    'もし1億円が当たったとしたら、何に使いますか。' => 'Moshi 1 oku en ga atatta to shitara, nan ni tsukaimasu ka.',
    'もし彼の話が本当だとしたら、大変なことになる。' => 'Moshi kare no hanashi ga hontou da to shitara, taihen na koto ni naru.',
    'もし明日世界が終わるとしたら、あなたは何をしますか。' => 'Moshi ashita sekai ga owaru to shitara, anata wa nan wo shimasu ka.',
    'もし今の仕事を辞めるとしたら、次は何をしたいですか。' => 'Moshi ima no shigoto wo yameru to shitara, tsugi wa nan wo shitai desu ka.',
    'もし明日雨が降ったとしたら、傘を持って出かけました。' => 'Moshi ashita ame ga futta to shitara, kasa wo motte dekakemashita.',
    'Struktur Dasar Kalimat Pasif dan Perubahan Urutan Subjek-Objek' => 'Struktur Dasar Kalimat Pasif dan Perubahan Urutan Subjek-Objek',
    'この本は有名な作家によって書かれた。' => 'Kono hon wa yuumei na sakka ni yotte kakareta.',
    'この橋は100年前に建てられた。' => 'Kono hashi wa 100 nen mae ni taterareta.',
    'その事件は警察に調べられている。' => 'Sono jiken wa keisatsu ni shiraberarete iru.',
    '先生が私に褒められました。' => 'Sensei ga watashi ni homeraremashita.',
    'Struktur Pasif Kerugian (迷惑の受身) dengan Verba Intransitif' => 'Struktur Pasif Kerugian (meiwaku no ukemi) dengan Verba Intransitif',
    '私は昨日雨に降られて、風邪をひいてしまった。' => 'Watashi wa kinou ame ni furarete, kaze wo hiite shimatta.',
    '夜遅く友達に来られて、勉強できなかった。' => 'Yoru osoku tomodachi ni korarete, benkyou dekinakatta.',
    '子供の頃、父に死なれて、生活が大変だった。' => 'Kodomo no koro, chichi ni shinarete, seikatsu ga taihen datta.',
    '電車の中で隣の人に足を踏まれた。' => 'Densha no naka de tonari no hito ni ashi wo fumareta.',
    '私は雨が降られて、困りました。' => 'Watashi wa ame ga furarete, komarimashita.',
    'Struktur Pasif untuk Pendapat Umum: と言われている／とされている' => 'Struktur Pasif untuk Pendapat Umum: to iwarete iru/to sarete iru',
    '日本語は習得が難しいと言われている。' => 'Nihon go wa shuutoku ga muzukashii to iwarete iru.',
    'この寺は800年前に建てられたとされている。' => 'Kono tera wa 800 nen mae ni taterareta to sarete iru.',
    '納豆は健康にいいと言われています。' => 'Nattou wa kenkou ni ii to iwarete imasu.',
    'その言語は消滅の危機にあるとされている。' => 'Sono gengo wa shoumetsu no kiki ni aru to sarete iru.',
    '医者が日本語は難しいと言われている。' => 'Isha ga Nihon go wa muzukashii to iwarete iru.',
    'Struktur Pasif-Kausatif (使役受身) dalam Kalimat Alasan' => 'Struktur Pasif-Kausatif (shieki ukemi) dalam Kalimat Alasan',
    '子供の頃、母に野菜を食べさせられました。' => 'Kodomo no koro, haha ni yasai wo tabesaseraremashita.',
    '上司に残業させられたので、帰りが遅くなった。' => 'Joushi ni zangyou saserareta no de, kaeri ga osoku natta.',
    '先生に3時間も待たせられて、とても疲れた。' => 'Sensei ni 3 jikan mo mataserarete, totemo tsukareta.',
    '飲みたくなかったのに、先輩に酒を飲まされた。' => 'Nomitaku nakatta no ni, senpai ni sake wo nomasareta.',
    '母が私に野菜を食べさせられました。' => 'Haha ga watashi ni yasai wo tabesaseraremashita.',
    'Struktur Pasif dengan によって untuk Karya dan Penemuan' => 'Struktur Pasif dengan ni yotte untuk Karya dan Penemuan',
    'この絵は有名な画家によって描かれた。' => 'Kono e wa yuumei na gaka ni yotte egakareta.',
    'この法律は国会によって制定された。' => 'Kono houritsu wa kokkai ni yotte seitei sareta.',
    'その理論は多くの科学者によって支持されている。' => 'Sono riron wa ooku no kagakusha ni yotte shiji sarete iru.',
    '私は先生によって褒められました。' => 'Watashi wa sensei ni yotte homeraremashita.',
    'Klausa Relatif sebagai Pewatas Nomina dalam Kalimat Bertingkat' => 'Klausa Relatif sebagai Pewatas Nomina dalam Kalimat Bertingkat',
    '昨日私が図書館で借りた本はとても面白かった。' => 'Kinou watashi ga toshokan de karita hon wa totemo omoshirokatta.',
    '彼が作った料理はいつもおいしい。' => 'Kare ga tsukutta ryouri wa itsu mo oishii.',
    '駅の近くに住んでいる友達を訪ねた。' => 'Eki no chikaku ni sunde iru tomodachi wo tazuneta.',
    '子供の時に読んだ物語を今でも覚えている。' => 'Kodomo no toki ni yonda monogatari wo ima de mo oboete iru.',
    '本、私が昨日買った、は面白かった。' => 'Hon, watashi ga kinou katta, wa omoshirokatta.',
    'Menyisipkan Klausa Kutipan と思う／と言う di Dalam Kalimat Lebih Besar' => 'Menyisipkan Klausa Kutipan to omou/to iu di Dalam Kalimat Lebih Besar',
    '私は彼が来年日本に留学すると思います。' => 'Watashi wa kare ga rainen Nihon ni ryuugaku suru to omoimasu.',
    '田中さんは会議に遅れると言っていました。' => 'Tanakasan wa kaigi ni okureru to itte imashita.',
    '彼女がその賞を受賞したと聞いて驚いた。' => 'Kanojo ga sono shou wo jushou shita to kiite odoroita.',
    '先生は、この問題は難しいと説明した。' => 'Sensei wa, kono mondai wa muzukashii to setsumei shita.',
    '彼は明日来ますと思います。' => 'Kare wa ashita kimasu to omoimasu.',
    'Nominalisasi の／こと untuk Menyisipkan Klausa sebagai Subjek atau Objek' => 'Nominalisasi no/koto untuk Menyisipkan Klausa sebagai Subjek atau Objek',
    '彼が歌を歌っているのが聞こえる。' => 'Kare ga uta wo utatte iru no ga kikoeru.',
    '毎日運動することは健康にいいです。' => 'Mainichi undou suru koto wa kenkou ni ii desu.',
    '私は彼が試験に合格したことを知らなかった。' => 'Watashi wa kare ga shiken ni goukaku shita koto wo shiranakatta.',
    '子供が公園で遊んでいるのを見た。' => 'Kodomo ga kouen de asonde iru no wo mita.',
    '早く起きるのを決めました。' => 'Hayaku okiru no wo kimemashita.',
    'Menyisipkan Klausa Pengandaian di Dalam Klausa Lain' => 'Menyisipkan Klausa Pengandaian di Dalam Klausa Lain',
    'もし時間があれば旅行に行きたいと思っています。' => 'Moshi jikan ga areba ryokou ni ikitai to omotte imasu.',
    '雨が降ったら試合は中止になるというルールがある。' => 'Ame ga futtara shiai wa chuushi ni naru to iu ruuru ga aru.',
    '彼は、もし失敗したらもう一度挑戦すると言っていた。' => 'Kare wa, moshi shippai shitara mou ichi do chousen suru to itte ita.',
    '安ければ買うという人が多かった。' => 'Yasukereba kau to iu hito ga ookatta.',
    '彼は、雨が降るなら、傘を持って行くと思う、と言った。' => 'Kare wa, ame ga furunara, kasa wo motte iku to omou, to itta.',
    'Menggabungkan Klausa Relatif dan Klausa Alasan dalam Satu Kalimat' => 'Menggabungkan Klausa Relatif dan Klausa Alasan dalam Satu Kalimat',
    '仕事が忙しかったので休んでいた社員が、今日から復帰した。' => 'Shigoto ga isogashikatta no de yasunde ita shain ga, kyou kara fukki shita.',
    '安いから人気がある店には、いつも行列ができている。' => 'Yasuikara ninki ga aru mise ni wa, itsu mo gyouretsu ga dekite iru.',
    '経験が少ないという理由で採用されなかった人が、別の会社で活躍している。' => 'Keiken ga sukunai to iu riyuu de saiyou sarenakatta hito ga, betsu no kaisha de katsuyaku shite iru.',
    '事故があったので通行止めになっている道路は、明日開通する予定だ。' => 'Jiko ga atta no de tsuukou tome ni natte iru douro wa, ashita kaitsuu suru yotei da.',
    '休んでいた社員は仕事が忙しかったのでが、今日から復帰した。' => 'Yasunde ita shain wa shigoto ga isogashikatta no dega, kyou kara fukki shita.',
    'Struktur Kalimat Belah (Cleft) dengan のは～だ' => 'Struktur Kalimat Belah (Cleft) dengan no wa~ da',
    '私がこの本を買ったのは、先週の日曜日です。' => 'Watashi ga kono hon wo katta no wa, senshuu no nichiyou hi desu.',
    '彼が怒っているのは、約束を破られたからだ。' => 'Kare ga okotte iru no wa, yakusoku wo yaburaretakara da.',
    'このケーキを作ったのは、母です。' => 'Kono keeki wo tsukutta no wa, haha desu.',
    '彼女が日本に来たのは、日本語を勉強するためだ。' => 'Kanojo ga Nihon ni kita no wa, Nihon go wo benkyou suru tame da.',
    '母がこのケーキを作ったのです。' => 'Haha ga kono keeki wo tsukutta no desu.',
    'Penekanan Kontras dengan Menempatkan Objek/Keterangan di Awal Kalimat' => 'Penekanan Kontras dengan Menempatkan Objek/Keterangan di Awal Kalimat',
    '肉は食べますが、魚は食べません。' => 'Niku wa tabemasuga, sakana wa tabemasen.',
    '日本語は難しいですが、英語は得意です。' => 'Nihon go wa muzukashii desuga, eigo wa tokui desu.',
    '東京には行ったことがありますが、大阪には行ったことがありません。' => 'Tokyo ni wa itta koto ga arimasuga, Osaka ni wa itta koto ga arimasen.',
    'この映画は見ましたが、あの映画はまだ見ていません。' => 'Kono eiga wa mimashitaga, ano eiga wa mada mite imasen.',
    '肉をは食べますが、魚をは食べません。' => 'Niku wo wa tabemasuga, sakana wo wa tabemasen.',
    'Penekanan Kuat dengan こそ' => 'Penekanan Kuat dengan koso',
    '今年こそ、日本語能力試験に合格したい。' => 'Kotoshi koso, Nihon go nouryoku shiken ni goukaku shitai.',
    'あなたの助けがあったからこそ、成功できたのです。' => 'Anata no tasuke ga attakara koso, seikou dekita no desu.',
    '失敗した時こそ、諦めずに頑張るべきだ。' => 'Shippai shita toki koso, akiramezu ni ganbarubekida.',
    'A：ありがとうございました。B：こちらこそ、ありがとうございました。' => 'A: arigatou gozaimashita. B: kochira koso, arigatou gozaimashita.',
    '今年こそが、日本語能力試験に合格したい。' => 'Kotoshi koso ga, Nihon go nouryoku shiken ni goukaku shitai.',
    'Fokus Pembatas dengan しか～ない' => 'Fokus Pembatas dengan shika~ nai',
    '財布には千円しかありません。' => 'Saifu ni wa sen en shika arimasen.',
    '彼はひらがなしか読めません。' => 'Kare wa hiragana shika yomemasen.',
    '今日は3時間しか寝ていない。' => 'Kyou wa 3 jikan shika nete inai.',
    'この問題は彼にしか解けない。' => 'Kono mondai wa kare ni shika tokenai.',
    '財布には千円しかあります。' => 'Saifu ni wa sen en shika arimasu.',
    'Penekanan Tambahan Ekstrem dengan さえ／すら' => 'Penekanan Tambahan Ekstrem dengan sae/sura',
    'この漢字は大人でさえ読めない。' => 'Kono kanji wa otona de sae yomenai.',
    '忙しすぎて、朝ご飯を食べる時間さえなかった。' => 'Isogashi sugite, asagohan wo taberu jikan sae nakatta.',
    '時間さえあれば、もっと勉強できるのに。' => 'Jikan sae areba, motto benkyou dekiru no ni.',
    '彼は自分の名前さえ書けないほど疲れていた。' => 'Kare wa jibun no namae sae kakenai hodo tsukarete ita.',
    '水さえ飲まなかったら、元気になります。' => 'Mizu sae nomanakattara, genki ni narimasu.',
    'Gaya である dalam Kalimat Tertulis Formal' => 'Gaya de aru dalam Kalimat Tertulis Formal',
    '経済成長の鈍化は、多くの要因が複雑に絡み合った結果である。' => 'Keizai seichou no donka wa, ooku no youin ga fukuzatsu ni karamiatta kekka de aru.',
    '本研究の目的は、若年層の消費行動を分析することである。' => 'Honkenkyuu no mokuteki wa, jakunen sou no shouhi koudou wo bunseki suru koto de aru.',
    '地球温暖化は、もはや無視できない問題である。' => 'Chikyuu ondanka wa, mohaya mushi dekinai mondai de aru.',
    '当時の社会情勢を理解することが不可欠である。' => 'Touji no shakai jousei wo rikai suru koto ga fukaketsu de aru.',
    'この論文の結論は明確であるが、データの分析はまだ不十分ですと言える。' => 'Kono ronbun no ketsuron wa meikaku de aruga, deeta no bunseki wa mada fujuubun desu to ieru.',
    '体言止め: Mengakhiri Kalimat dengan Kata Benda' => 'Taigen tome: Mengakhiri Kalimat dengan Kata Benda',
    '今回の事故の原因は、整備不良という単純なミス。' => 'Konkai no jiko no gen\'in wa, seibi furyou to iu tanjun na misu.',
    '新製品の最大の特徴は、圧倒的な省エネ性能。' => 'Shinseihin no saidai no tokuchou wa, attouteki na shouene seinou.',
    '長引く不況の中で求められているのは、大胆な改革。' => 'Nagabiku fukyou no naka de motomerarete iru no wa, daitan na kaikaku.',
    '彼が最後に残した言葉は、家族への深い感謝。' => 'Kare ga saigo ni nokoshita kotoba wa, kazoku e no fukai kansha.',
    '記事の見出しとして「新技術が発表されましただ」と書いた。' => 'Kiji no midashi to shite "shingijutsu ga happyou saremashitada" to kaita.',
    'Klausa Pewatas Panjang Sebelum Kata Benda Inti' => 'Klausa Pewatas Panjang Sebelum Kata Benda Inti',
    '長年にわたって地域住民が反対し続けてきた計画が、ついに中止されることになった。' => 'Naganen ni watatte chiiki juumin ga hantai shi tsuzukete kita keikaku ga, tsuini chuushi sareru koto ni natta.',
    '専門家が繰り返し警告してきた気候変動のリスクが、現実のものとなりつつある。' => 'Senmonka ga kurikaeshi keikoku shite kita kikou hendou no risuku ga, genjitsu no mono to naritsutsu aru.',
    '政府が昨年発表したものの実施が延期されていた政策が、今月から施行される。' => 'Seifu ga sakunen happyou shita mono no jisshi ga enki sarete ita seisaku ga, kongetsu kara shikou sareru.',
    '若い世代の間で急速に広がりつつある新しい働き方が、企業文化を大きく変えようとしている。' => 'Wakai sedai no aida de kyuusoku ni hirogaritsutsu aru atarashii hatarakikata ga, kigyou bunka wo ookiku kaeyou to shite iru.',
    '計画が中止された。それは長年住民が反対していた。そして先月決定した。' => 'Keikaku ga chuushi sareta. sore wa naganen juumin ga hantai shite ita. soshite sengetsu kettei shita.',
    'Penutup Penjelas ～のである di Akhir Kalimat Formal' => 'Penutup Penjelas ~ no de aru di Akhir Kalimat Formal',
    'つまり、教育制度そのものを根本から見直す必要があるのである。' => 'Tsumari, kyouiku seido sono mono wo konpon kara minaosu hitsuyou ga aru no de aru.',
    '彼らは決してあきらめなかった。だからこそ成功を収めたのである。' => 'Karera wa kesshite akiramenakatta. dakara koso seikou wo osameta no de aru.',
    'この現象は単なる偶然ではなく、長年の構造的な問題が表面化したのである。' => 'Kono genshou wa tannaru guuzen de wa naku, naganen no kouzouteki na mondai ga hyoumenka shita no de aru.',
    '技術の進歩が、かえって人々の孤立を深めているのである。' => 'Gijutsu no shinpo ga, kaette hitobito no koritsu wo fukamete iru no de aru.',
    '昨日、友達とカフェに行ったのである。' => 'Kinou, tomodachi to kafe ni itta no de aru.',
    'Klausa Situasional di Awal Kalimat: ～にあたり／～に際して' => 'Klausa Situasional di Awal Kalimat: ~ ni atari/~ ni saishite',
    '新年度を迎えるにあたり、社員一同さらなる努力を誓います。' => 'Shinnendo wo mukaeru ni atari, shain ichidou saranaru doryoku wo chikaimasu.',
    'このプロジェクトを開始するに際して、改めて目標を確認しておきたい。' => 'Kono purojekuto wo kaishi suru ni saishite, aratamete mokuhyou wo kakunin shite okitai.',
    '契約を締結するにあたり、双方は以下の条件に合意した。' => 'Keiyaku wo teiketsu suru ni atari, souhou wa ika no jouken ni goui shita.',
    '式典の開催に際して、来賓を代表してご挨拶申し上げます。' => 'Shikiten no kaisai ni saishite, raihin wo daihyou shite goaisatsu moushiagemasu.',
    '友達の家に遊びに行くにあたり、お菓子を買った。' => 'Tomodachi no ie ni asobi ni iku ni atari, okashi wo katta.',
    '～ものの: Klausa Konsesif Formal Standar' => '~ mono no: Klausa Konsesif Formal Standar',
    '売上は改善したものの、依然として目標には届いていない。' => 'Uriage wa kaizen shita mono no, izen to shite mokuhyou ni wa todoite inai.',
    '彼は謝罪したものの、誰も彼を許そうとしなかった。' => 'Kare wa shazai shita mono no, dare mo kare wo yurusou to shinakatta.',
    '新しい制度は導入されたものの、現場ではほとんど機能していない。' => 'Atarashii seido wa dounyuu sareta mono no, genba de wa hotondo kinou shite inai.',
    '説明を受けたものの、まだ理解できない点が多い。' => 'Setsumei wo uketa mono no, mada rikai dekinai ten ga ooi.',
    '雨が降っているものの、傘を持っていきなさい。' => 'Ame ga futte iru mono no, kasa wo motte iki nasai.',
    '～にもかかわらず: Kontras Kuat dengan Kenyataan' => '~ ni mo kakawarazu: Kontras Kuat dengan Kenyataan',
    '警告を受けたにもかかわらず、彼は同じ過ちを繰り返した。' => 'Keikoku wo uketa ni mo kakawarazu, kare wa onaji ayamachi wo kurikaeshita.',
    '深夜であるにもかかわらず、多くの人が駅前に集まっていた。' => 'Shin\'ya de aru ni mo kakawarazu, ooku no hito ga ekimae ni atsumatte ita.',
    '努力したにもかかわらず、結果は期待外れだった。' => 'Doryoku shita ni mo kakawarazu, kekka wa kitaihazure datta.',
    '悪天候にもかかわらず、イベントは予定通り開催された。' => 'Akutenkou ni mo kakawarazu, ibento wa yotei toori kaisai sareta.',
    '疲れているにもかかわらず、少し休んだほうがいい。' => 'Tsukarete iru ni mo kakawarazu, sukoshi yasunda hou ga ii.',
    '～つつも: Konsesif dengan Subjek Tunggal Bersamaan' => '~ tsutsu mo: Konsesif dengan Subjek Tunggal Bersamaan',
    '体に悪いとわかりつつも、彼はタバコをやめられない。' => 'Karada ni warui to wakaritsutsu mo, kare wa tabako wo yamerarenai.',
    '忙しいと言いつつも、彼女は毎晩ドラマを見ている。' => 'Isogashii to iitsutsu mo, kanojo wa maiban dorama wo mite iru.',
    '反対しつつも、結局は上司の指示に従った。' => 'Hantai shitsutsu mo, kekkyoku wa joushi no shiji ni shitagatta.',
    '不安を感じつつも、新しい挑戦に踏み出すことにした。' => 'Fuan wo kanjitsutsu mo, atarashii chousen ni fumidasu koto ni shita.',
    '雨が降りつつも、試合は中止になった。' => 'Ame ga oritsutsu mo, shiai wa chuushi ni natta.',
    'とはいえ: Penghubung Konsesif Antarkalimat' => 'To wa ie: Penghubung Konsesif Antarkalimat',
    '景気は回復しつつある。とはいえ、まだ油断はできない。' => 'Keiki wa kaifuku shitsutsu aru. to wa ie, mada yudan wa dekinai.',
    '彼の意見には一理ある。とはいえ、全面的に賛成はできない。' => 'Kare no iken ni wa ichiri aru. to wa ie, zenmenteki ni sansei wa dekinai.',
