    '子供とはいえ、その発言は許されるものではない。' => 'Kodomo to wa ie, sono hatsugen wa yurusareru mono de wa nai.',
    '疲れた、とはいえ頑張ります。' => 'Tsukareta, to wa ie ganbarimasu.',
    '～ながらも: Konsesif Menekankan Keadaan Tetap' => '~nagara mo: Konsesif Menekankan Keadaan Tetap',
    '小さいながらも、この店は地域で高い評価を得ている。' => 'Chiisainagara mo, kono mise wa chiiki de takai hyouka wo ete iru.',
