    '彼が事故に遭ったことを見た。' => 'Kare ga jiko ni atta koto wo mita.',
    'こと Nominalisasi untuk Topik Abstrak dan Pernyataan' => 'Koto Nominalisasi untuk Topik Abstrak dan Pernyataan',
    '毎日運動することは、健康維持にとって重要だ。' => 'Mainichi undou suru koto wa, kenkou iji ni totte juuyou da.',
