    '道が混んでいる。事故があったのだ。' => 'Michi ga konde iru. jiko ga atta no da.',
    '健康を保つ秘訣は、規則正しい生活を送ることだ。' => 'Kenkou wo tamotsu hiketsu wa, kisoku tadashii seikatsu wo okuru koto da.',
