    '彼女は誰よりも早く昇進した。誰よりも努力していたからだ。' => 'Kanojo wa dare yori mo hayaku shoushin shita. dare yori mo doryoku shite itakara da.',
    '町の人口は急激に減少している。若者が都市部へ流出しているからだ。' => 'Machi no jinkou wa kyuugeki ni genshou shite iru. wakamono ga toshi bu e ryuushutsu shite irukara da.',
