    '明日晴れたら。絶対に行くよ。' => 'Ashita haretara. zettai ni iku yo.',
    'Inversi Elemen Emosi/Seruan ke Posisi Akhir' => 'Inversi Elemen Emosi/Seruan ke Posisi Akhir',
    'あの映画は、本当に素晴らしかった。' => 'Ano eiga wa, hontou ni subarashikatta.',
    '彼の態度は、あまりにも無責任だ。' => 'Kare no taido wa, amari ni mo musekinin da.',
