    '彼女の決断は、驚くほど早かった。' => 'Kanojo no ketsudan wa, odoroku hodo hayakatta.',
    '素晴らしかった、あの映画。' => 'Subarashikatta, ano eiga.',
    '～たり～たりする: Struktur Paralel Tindakan Representatif' => '~ tari~ tari suru: Struktur Paralel Tindakan Representatif',
    '週末は、映画を見たり本を読んだりして過ごした。' => 'Shuumatsu wa, eiga wo mi tari hon wo yon dari shite sugoshita.',
    '子供たちは公園で走ったり跳んだりして遊んでいる。' => 'Kodomotachi wa kouen de hashit tari ton dari shite asonde iru.',
    '会議中、資料を確認したりメモを取ったりする必要がある。' => 'Kaigichuu, shiryou wo kakunin shi tari memo wo tot tari suru hitsuyou ga aru.',
    '天気が良い日は、洗濯をしたり掃除をしたりする。' => 'Tenki ga yoi hi wa, sentaku wo shi tari souji wo shi tari suru.',
    '休みの日は、映画を見たり本を読む。' => 'Yasumi no hi wa, eiga wo mi tari hon wo yomu.',
    '～し～し: Struktur Paralel Alasan/Fakta Majemuk' => '~ shi~ shi: Struktur Paralel Alasan/Fakta Majemuk',
    'この店は値段も安いし、味もいいし、いつも混んでいる。' => 'Kono mise wa nedan mo yasuishi, aji mo iishi, itsu mo konde iru.',
    '今日は雨が降っているし、風も強いし、外出はやめたほうがいい。' => 'Kyou wa ame ga futte irushi, kaze mo tsuyoishi, gaishutsu wa yameta hou ga ii.',
    '彼は経験も豊富だし、知識もあるし、リーダーにふさわしい。' => 'Kare wa keiken mo houfu dashi, chishiki mo arushi, riidaa ni fusawashii.',
    '時間もないし、お金もないし、今回は諦めるしかない。' => 'Jikan mo naishi, okane mo naishi, konkai wa akirameru shika nai.',
    'この部屋は狭いし暗いから、あまり好きじゃない。' => 'Kono heya wa semaishi kuraikara, amari suki ja nai.',
    '～や～（など）: Struktur Paralel Daftar Kata Benda Tidak Lengkap' => '~ ya~ (nado): Struktur Paralel Daftar Kata Benda Tidak Lengkap',
    '冷蔵庫には、野菜や果物などが入っている。' => 'Reizouko ni wa, yasai ya kudamono nado ga haitte iru.',
    'このイベントには、学生や社会人など、幅広い層が参加している。' => 'Kono ibento ni wa, gakusei ya shakainin nado, habahiroi sou ga sanka shite iru.',
    '休日は、読書や散歩などをして過ごすことが多い。' => 'Kyuujitsu wa, dokusho ya sanpo nado wo shite sugosu koto ga ooi.',
    '会議では、コストや納期などについて話し合われた。' => 'Kaigi de wa, kosuto ya nouki nado ni tsuite hanashiawareta.',
    '参加者は田中さんと鈴木さんや佐藤さんです。' => 'Sankasha wa Tanakasan to Suzukisan ya Satousan desu.',
    '～なり～なり: Struktur Paralel Alternatif Setara' => '~ nari~ nari: Struktur Paralel Alternatif Setara',
    'わからないことがあれば、先生に聞くなり、自分で調べるなりしなさい。' => 'Wakaranai koto ga areba, sensei ni kikunari, jibun de shiraberu nari shi nasai.',
    '意見があるなら、メールを送るなり、直接話すなりしてください。' => 'Iken ga arunara, meeru wo okurunari, chokusetsu hanasu nari shite kudasai.',
    '体調が悪いなら、病院に行くなり、家で休むなりしたほうがいい。' => 'Taichou ga waruinara, byouin ni ikunari, ie de yasumu nari shita hou ga ii.',
    '不要な物は、売るなり、捨てるなりして片付けたほうがいい。' => 'Fuyou na mono wa, urunari, suteru nari shite katazuketa hou ga ii.',
    '好きな料理はラーメンなりカレーなりです。' => 'Suki na ryouri wa raamennari kareenari desu.',
    '～とともに／～と同時に: Struktur Paralel Peristiwa Simultan' => '~ to tomo ni/~ to douji ni: Struktur Paralel Peristiwa Simultan',
    '技術の発展とともに、人々の生活は大きく変化してきた。' => 'Gijutsu no hatten to tomo ni, hitobito no seikatsu wa ookiku henka shite kita.',
    '人口が減少すると同時に、地域経済も縮小しつつある。' => 'Jinkou ga genshou suruto douji ni, chiiki keizai mo shukushou shitsutsu aru.',
    '彼は会社の代表であると同時に、二人の子供の父親でもある。' => 'Kare wa kaisha no daihyou de aru to douji ni, futari no kodomo no chichioya de mo aru.',
    '都市化が進むとともに、自然環境の破壊が深刻化している。' => 'Toshika ga susumu to tomo ni, shizen kankyou no hakai ga shinkokuka shite iru.',
    '雨が降ったとともに、試合が中止になった。' => 'Ame ga futta to tomo ni, shiai ga chuushi ni natta.',
    'Inversi Predikat-Subjek untuk Efek Dramatis (倒置法)' => 'Inversi Predikat-Subjek untuk Efek Dramatis (touchi hou)',
    '消えた、あの日見た光は。' => 'Kieta, ano hi mita hikari wa.',
    '美しい、この国の四季は。' => 'Utsukushii, kono kuni no shiki wa.',
