    '報告書に「消えた、あの日見た光は。」のような倒置文を用いた。' => 'Houkokusho ni "kieta, ano hi mita hikari wa." no you na touchi bun wo mochiita.',
    'Kalimat Tanya Retoris untuk Menegaskan Sebaliknya (反語)' => 'Kalimat Tanya Retoris untuk Menegaskan Sebaliknya (hango)',
    'こんな理不尽なことが許されるものか。' => 'Konna ri fujin na koto ga yurusareru mono ka.',
    '誰がこの苦しみを理解できるだろうか、いや、誰にも理解できまい。' => 'Dare ga kono kurushimi wo rikai dekirudarou ka, iya, dare ni mo rikai dekimai.',
    '努力なくして成功などあり得ようか。' => 'Doryoku naku shite seikou nado ari eyou ka.',
    'これが正義と言えるだろうか。' => 'Kore ga seigi to ierudarou ka.',
    '相手に本当に答えを求めて「これが正義と言えるだろうか」と尋ねたが、返事がないことに驚いた。' => 'Aite ni hontou ni kotae wo motomete "kore ga seigi to ierudarou ka" to tazunetaga, henji ga nai koto ni odoroita.',
    'Struktur Paralelisme Klasik ~も~ば、~も~' => 'Struktur Paralelisme Klasik ~ mo~ba,~ mo~',
    '光もあれば影もある、それが人生というものだ。' => 'Hikari mo areba kage mo aru, sore ga jinsei to iu mono da.',
    '喜びもあれば悲しみもあるのが、旅の醍醐味だ。' => 'Yorokobi mo areba kanashimi mo aru no ga, tabi no daigomi da.',
    '成功もあれば失敗もある、それを恐れてはならない。' => 'Seikou mo areba shippai mo aru, sore wo osorete wa naranai.',
    '春もあれば冬もある、その移ろいこそ日本の美である。' => 'Haru mo areba fuyu mo aru, sono utsuroi koso Nihon no bi de aru.',
    '光もあるし影もあるし、それが人生だ。' => 'Hikari mo arushi kage mo arushi, sore ga jinsei da.',
    'Negasi Klasik Retoris ~ずして~か' => 'Negasi Klasik Retoris ~ zu shite~ ka',
    '努力せずして、栄光を手にすることができようか。' => 'Doryoku sezu shite, eikou wo te ni suru koto ga dekiyou ka.',
    '苦難を経ずして、真の成長はあり得ない。' => 'Kunan wo hezu shite, shin no seichou wa ari enai.',
    '対話なくして、平和はあり得ない。' => 'Taiwa naku shite, heiwa wa ari enai.',
    '涙なくして、この物語を読むことはできない。' => 'Namida naku shite, kono monogatari wo yomu koto wa dekinai.',
    '日常会話で友人に「勉強せずして、テストに合格できようか」と話した。' => 'Nichijou kaiwa de yuujin ni "benkyou sezu shite, tesuto ni goukaku dekiyou ka" to hanashita.',
    'Kalimat Berakhir Nomina untuk Efek Estetis (体言止め)' => 'Kalimat Berakhir Nomina untuk Efek Estetis (taigen tome)',
    '静まり返った、あの夜の海。' => 'Shizumarikaetta, ano yoru no umi.',
    '忘れられない、あの日の約束。' => 'Wasurerarenai, ano hi no yakusoku.',
    '窓の外に広がるのは、一面の桜。' => 'Mado no soto ni hirogaru no wa, ichimen no sakura.',
    '彼が最後に見たのは、故郷の夕焼け。' => 'Kare ga saigo ni mita no wa, kokyou no yuuyake.',
    '学術論文の結論部分で「本研究が示すのは、新たな可能性。」のように体言止めで文を終えた。' => 'Gakujutsu ronbun no ketsuron bubun de "honkenkyuu ga shimesu no wa, arata na kanousei." no you ni taigen tome de bun wo oeta.',
    'Struktur Tesis Berpagar dengan ~と考えられる' => 'Struktur Tesis Berpagar dengan ~ to kangaerareru',
    '以上のデータから、両者の間には強い相関関係があると考えられる。' => 'Ijou no deeta kara, ryousha no aida ni wa tsuyoi soukan kankei ga aru to kangaerareru.',
    'この結果は、従来の理論では説明が困難であると言えよう。' => 'Kono kekka wa, juurai no riron de wa setsumei ga konnan de aru to ieyou.',
    '今後さらなる検証が必要であると思われる。' => 'Kongo saranaru kenshou ga hitsuyou de aru to omowareru.',
    '本調査の限界を踏まえると、結論の一般化には慎重を期すべきだと考えられる。' => 'Honchousa no genkai wo fumaeruto, ketsuron no ippanka ni wa shinchou wo kisubekida to kangaerareru.',
    '論文の結論で「この理論は間違っている。」と断定的に書いた。' => 'Ronbun no ketsuron de "kono riron wa machigatte iru." to danteiteki ni kaita.',
    'Klausa Pembingkai Awal Kalimat ~において / ~にとって' => 'Klausa Pembingkai Awal Kalimat ~ ni oite/~ ni totte',
    '現代社会において、情報の信頼性を見極める能力はますます重要になっている。' => 'Gendai shakai ni oite, jouhou no shinraisei wo mikiwameru nouryoku wa masumasu juuyou ni natte iru.',
    '発展途上国にとって、教育への投資は経済成長の鍵となる。' => 'Hatten tojoukoku ni totte, kyouiku e no toushi wa keizai seichou no kagi to naru.',
    '本研究において、対象者の選定は無作為抽出法によって行われた。' => 'Honkenkyuu ni oite, taishousha no sentei wa musakui chuushutsu hou ni yotte okonawareta.',
    '言語習得の過程において、母語の影響は無視できない要素である。' => 'Gengo shuutoku no katei ni oite, bogo no eikyou wa mushi dekinai youso de aru.',
    '本研究の対象者は無作為抽出法によって選定された、大学生において。' => 'Honkenkyuu no taishousha wa musakui chuushutsu hou ni yotte sentei sareta, daigakusei ni oite.',
    'Struktur Argumentasi Konsesif-Akademik ~とはいえ、~ざるを得ない' => 'Struktur Argumentasi Konsesif-Akademik ~ to wa ie,~ zaru wo enai',
    '技術は進歩したとはいえ、人間の判断力の重要性は依然として否定できない。' => 'Gijutsu wa shinpo shita to wa ie, ningen no handanryoku no juuyousei wa izen to shite hitei dekinai.',
    '一定の成果が見られたとはいえ、根本的な問題は未解決のままだと言わざるを得ない。' => 'Ittei no seika ga mirareta to wa ie, konponteki na mondai wa mikaiketsu no mama da to iwazaru wo enai.',
    '反対意見も理解できるとはいえ、データが示す傾向を無視するわけにはいかない。' => 'Hantai iken mo rikai dekiru to wa ie, deeta ga shimesu keikou wo mushi suru wake ni wa ikanai.',
    'サンプル数が限られていたとはいえ、この結果には一定の示唆があると言わざるを得ない。' => 'Sanpuru suu ga kagirarete ita to wa ie, kono kekka ni wa ittei no shisa ga aru to iwazaru wo enai.',
    '技術は進歩したとはいえ、人間の判断力の重要性は否定できないかもしれない。' => 'Gijutsu wa shinpo shita to wa ie, ningen no handanryoku no juuyousei wa hitei dekinai ka mo shirenai.',
    'Rantai Nominalisasi Kausal ~ことによって / ~ことに起因する' => 'Rantai Nominalisasi Kausal ~ koto ni yotte/~ koto ni kiin suru',
    '都市部への人口集中が進んだことによって、地方の過疎化が一層深刻化した。' => 'Toshi bu e no jinkou shuuchuu ga susunda koto ni yotte, chihou no kasoka ga issou shinkokuka shita.',
    'この現象は、気候変動によって海水温が上昇したことに起因すると考えられている。' => 'Kono genshou wa, kikou hendou ni yotte kaisuion ga joushou shita koto ni kiin suru to kangaerarete iru.',
    '情報技術を導入することによって、業務の効率が大幅に改善された。' => 'Jouhou gijutsu wo dounyuu suru koto ni yotte, gyoumu no kouritsu ga oohaba ni kaizen sareta.',
    'この誤差は、測定機器の較正が不十分であったことに起因する可能性がある。' => 'Kono gosa wa, sokutei kiki no kousei ga fujuubun de atta koto ni kiin suru kanousei ga aru.',
    '都市部へ人が集中したので、過疎化が進んだことによって深刻化した。' => 'Toshi bu e hito ga shuuchuu shita no de, kasoka ga susunda koto ni yotte shinkokuka shita.',
    'Struktur Kondisional-Argumentatif 仮に~としても、~にほかならない' => 'Struktur Kondisional-Argumentatif kari ni~ to shite mo,~ ni hoka naranai',
    '仮にこの政策が短期的には効果を上げたとしても、長期的な弊害を軽視した結果にほかならない。' => 'Kari ni kono seisaku ga tankiteki ni wa kouka wo ageta to shite mo, choukiteki na heigai wo keishi shita kekka ni hoka naranai.',
    '仮に統計上の誤差が存在するとしても、この傾向は明白な変化の兆候にほかならない。' => 'Kari ni toukeijou no gosa ga sonzai suru to shite mo, kono keikou wa meihaku na henka no choukou ni hoka naranai.',
    '仮に一部の例外が認められるとしても、それは周辺的な現象にほかならない。' => 'Kari ni ichibu no reigai ga mitomerareru to shite mo, sore wa shuuhenteki na genshou ni hoka naranai.',
    '仮に予算の制約があったとしても、計画の失敗は準備不足に起因するものにほかならない。' => 'Kari ni yosan no seiyaku ga atta to shite mo, keikaku no shippai wa junbi fusoku ni kiin suru mono ni hoka naranai.',
    '仮にこの政策が効果を上げたとしても、長期的な弊害があるかもしれない。' => 'Kari ni kono seisaku ga kouka wo ageta to shite mo, choukiteki na heigai ga aru ka mo shirenai.',
    'Kutipan Berlapis Ganda ~と述べたと' => 'Kutipan Berlapis Ganda ~ to nobeta to',
    '委員長は、専門家が「この技術にはリスクが伴う」と指摘したと説明した。' => 'Iinchou wa, senmonka ga "kono gijutsu ni wa risuku ga tomonau" to shiteki shita to setsumei shita.',
    '記者は、目撃者が「爆発音が二回聞こえた」と証言したと報じた。' => 'Kisha wa, mokugekisha ga "bakuhatsu on ga ni kai kikoeta" to shougen shita to houjita.',
    '教授は、著者が本の中で「この理論はもはや通用しない」と主張していたと紹介した。' => 'Kyouju wa, chosha ga hon no naka de "kono riron wa mohaya tsuuyou shinai" to shuchou shite ita to shoukai shita.',
    '首相は、担当大臣が「対策はすでに講じられている」と報告したと述べた。' => 'Shushou wa, tantou daijin ga "taisaku wa sudeni koujirarete iru" to houkoku shita to nobeta.',
    '委員長は専門家がこの技術にはリスクが伴う指摘したと説明した。' => 'Iinchou wa senmonka ga kono gijutsu ni wa risuku ga tomonau shiteki shita to setsumei shita.',
    'Struktur Laporan Formal ~との報告がある' => 'Struktur Laporan Formal ~ to no houkoku ga aru',
    '研究チームからは、新薬の副作用は軽微であるとの報告がある。' => 'Kenkyuu chiimu kara wa, shin\'yaku no fukusayou wa keibi de aru to no houkoku ga aru.',
    '専門家は、この傾向は今後も続くだろうとの見解を示した。' => 'Senmonka wa, kono keikou wa kongo mo tsuzukudarou to no kenkai wo shimeshita.',
    '当局は、事故の原因はまだ特定されていないとの立場を崩していない。' => 'Toukyoku wa, jiko no gen\'in wa mada tokutei sarete inai to no tachiba wo kuzushite inai.',
    '一部の学者からは、この解釈には再考の余地があるとの指摘がなされている。' => 'Ichibu no gakusha kara wa, kono kaishaku ni wa saikou no yochi ga aru to no shiteki ga nasarete iru.',
    '新薬の副作用は軽微であると報告がある。' => 'Shin\'yaku no fukusayou wa keibi de aru to houkoku ga aru.',
    'Kutipan Bertingkat dengan Klausa Sikap ~という考えを示した' => 'Kutipan Bertingkat dengan Klausa Sikap ~ to iu kangae wo shimeshita',
    '賛成派は経済効果が期待できるという考えを示した一方、反対派は環境への影響を懸念するという立場を崩さなかった。' => 'Sanseiha wa keizai kouka ga kitai dekiru to iu kangae wo shimeshita ippou, hantaiha wa kankyou e no eikyou wo kenen suru to iu tachiba wo kuzusanakatta.',
    '彼は、規制を強化すべきだという考えを一貫して示している。' => 'Kare wa, kisei wo kyouka subekida to iu kangae wo ikkan shite shimeshite iru.',
    '委員の一部は、この計画は時期尚早であるという見方を示した。' => 'Iin no ichibu wa, kono keikaku wa jiki shousou de aru to iu mikata wo shimeshita.',
    '著者は本書の中で、教育こそが社会を変える力であるという考えを繰り返し述べている。' => 'Chosha wa honsho no naka de, kyouiku koso ga shakai wo kaeru chikara de aru to iu kangae wo kurikaeshi nobete iru.',
    '賛成派は経済効果が期待できるという考えを示したが、反対派は環境への影響を懸念すると考えを崩さなかった。' => 'Sanseiha wa keizai kouka ga kitai dekiru to iu kangae wo shimeshitaga, hantaiha wa kankyou e no eikyou wo kenen suru to kangae wo kuzusanakatta.',
    'Kutipan dalam Klausa Relatif ~と主張する学者' => 'Kutipan dalam Klausa Relatif ~ to shuchou suru gakusha',
    '言語は思考を規定すると主張する学者は、今なお一定数存在する。' => 'Gengo wa shikou wo kitei suru to shuchou suru gakusha wa, ima nao ittei suu sonzai suru.',
    '経済成長こそが貧困解決の鍵であると論じる専門家に対し、批判的な見解を持つ者も少なくない。' => 'Keizai seichou koso ga hinkon kaiketsu no kagi de aru to ronjiru senmonka ni taishi, hihanteki na kenkai wo motsu mono mo sukunaku nai.',
    'この制度は本質的に不公平であると訴える団体が、近年増加している。' => 'Kono seido wa honshitsuteki ni fukouhei de aru to uttaeru dantai ga, kinnen zouka shite iru.',
    '気候変動は人為的な要因によるものだと断言する研究者たちの主張は、国際的な合意の基盤となっている。' => 'Kikou hendou wa jin\'iteki na youin ni yoru mono da to dangen suru kenkyuushatachi no shuchou wa, kokusaiteki na goui no kiban to natte iru.',
    '言語は思考を規定すると主張する学者が今なお一定数存在すると考える。' => 'Gengo wa shikou wo kitei suru to shuchou suru gakusha ga ima nao ittei suu sonzai suru to kangaeru.',
    'Rantai Kutipan Berjenjang ~によれば、~という' => 'Rantai Kutipan Berjenjang ~ ni yoreba,~ to iu',
    '関係者の話によれば、担当部署はすでに対応を検討しているとのことだ。' => 'Kankeisha no hanashi ni yoreba, tantou busho wa sudeni taiou wo kentou shite iru to no koto da.',
    '現地紙の報道によれば、当局者は事態は収束に向かっていると述べたという。' => 'Genchishi no houdou ni yoreba, toukyokusha wa jitai wa shuusoku ni mukatte iru to nobeta to iu.',
    '専門家によれば、この現象は過去の事例から見ても異例だという。' => 'Senmonka ni yoreba, kono genshou wa kako no jirei kara mite mo irei da to iu.',
    '内部資料によれば、当時の経営陣はリスクを認識していながら対策を怠ったとされている。' => 'Naibu shiryou ni yoreba, touji no keiei jin wa risuku wo ninshiki shite inagara taisaku wo okotatta to sarete iru.',
    '関係者の話によれば、担当部署はすでに対応を検討している。' => 'Kankeisha no hanashi ni yoreba, tantou busho wa sudeni taiou wo kentou shite iru.',
    'Struktur Topik-Komentar Berlapis ~というのは~ということだ' => 'Struktur Topik-Komentar Berlapis ~ to iu no wa~ to iu koto da',
    '本当の自由というのは、何をしてもいいということではなく、自らの行動に責任を持てるということだ。' => 'Hontou no jiyuu to iu no wa, nan wo shite mo ii to iu koto de wa naku, mizukara no koudou ni sekinin wo moteru to iu koto da.',
    '教養があるというのは、単に知識が多いということではなく、それをどう活かすかを知っているということだ。' => 'Kyouyou ga aru to iu no wa, tanni chishiki ga ooi to iu koto de wa naku, sore wo dou ikasu ka wo shitte iru to iu koto da.',
    '成熟するというのは、自分の弱さを受け入れられるようになるということだ。' => 'Seijuku suru to iu no wa, jibun no yowasa wo ukeirerareru you ni naru to iu koto da.',
    '信頼を築くというのは、一朝一夕にできることではなく、小さな約束を積み重ねていくということだ。' => 'Shinrai wo kizuku to iu no wa, itchou isseki ni dekiru koto de wa naku, chiisana yakusoku wo tsumikasanete iku to iu koto da.',
    '本当の自由というのは、何をしてもいいということではなく、自らの行動に責任を持てる。' => 'Hontou no jiyuu to iu no wa, nan wo shite mo ii to iu koto de wa naku, mizukara no koudou ni sekinin wo moteru.',
    'Penumpukan Klausa Subordinat: Sebab, Syarat, dan Konsesi' => 'Penumpukan Klausa Subordinat: Sebab, Syarat, dan Konsesi',
    '予算が限られているため、全ての要望に応えられるならば理想的であるものの、現実には優先順位をつけざるを得ない。' => 'Yosan ga kagirarete iru tame, subete no youbou ni kotaerarerunaraba risouteki de aru mono no, genjitsu ni wa yuusen jun\'i wo tsukezaru wo enai.',
    '気候が急変したことにより、計画通りに進めば問題はなかったものの、結局スケジュールの見直しを迫られた。' => 'Kikou ga kyuuhen shita koto ni yori, keikaku toori ni susumeba mondai wa nakatta mono no, kekkyoku sukejuuru no minaoshi wo semarareta.',
    '人手が不足しているため、機械化を進めれば効率は上がるはずであるものの、初期投資の負担が大きい。' => 'Hitode ga fusoku shite iru tame, kikaika wo susumereba kouritsu wa agaru hazu de aru mono no, shoki toushi no futan ga ookii.',
    '情報が錯綜しているため、確認さえ取れれば混乱は避けられたものの、対応が後手に回ってしまった。' => 'Jouhou ga sakusou shite iru tame, kakunin sae torereba konran wa sakerareta mono no, taiou ga gote ni mawatte shimatta.',
    '予算が限られているので、全ての要望に応えられるが、優先順位をつけざるを得ない。' => 'Yosan ga kagirarete iru no de, subete no youbou ni kotaerareruga, yuusen jun\'i wo tsukezaru wo enai.',
    'Rantai Nominalisasi sebagai Subjek Kompleks ~ということが~を意味する' => 'Rantai Nominalisasi sebagai Subjek Kompleks ~ to iu koto ga~ wo imi suru',
    '若年層の投票率が年々低下しているということは、政治への関心そのものが薄れていることを意味するわけではない。' => 'Jakunen sou no touhyou ritsu ga nennen teika shite iru to iu koto wa, seiji e no kanshin sono mono ga usurete iru koto wo imi suru wake de wa nai.',
    '多くの企業が在宅勤務を導入し始めたということは、働き方に対する価値観が根本から変化しつつあることを示している。' => 'Ooku no kigyou ga zaitaku kinmu wo dounyuu shi hajimeta to iu koto wa, hatarakikata ni taisuru kachikan ga konpon kara henka shitsutsu aru koto wo shimeshite iru.',
    '同じ実験を繰り返しても同様の結果が得られたということが、この理論の妥当性を裏付けている。' => 'Onaji jikken wo kurikaeshite mo douyou no kekka ga erareta to iu koto ga, kono riron no datousei wo urazukete iru.',
    '彼が最後まで反論しなかったということは、内心では納得していたことを物語っているのかもしれない。' => 'Kare ga saigo made hanron shinakatta to iu koto wa, naishin de wa nattoku shite ita koto wo monogatatte iru no ka mo shirenai.',
    '若年層の投票率が低下している、それは政治への関心が薄れていることを意味しない。' => 'Jakunen sou no touhyou ritsu ga teika shite iru, sore wa seiji e no kanshin ga usurete iru koto wo imi shinai.',
    'Penumpukan Klausa Relatif Berlapis pada Nomina Inti' => 'Penumpukan Klausa Relatif Berlapis pada Nomina Inti',
    '先週発表された調査結果が示している傾向を裏付ける新たなデータが、今回の会議で提出された。' => 'Senshuu happyou sareta chousa kekka ga shimeshite iru keikou wo urazukeru arata na deeta ga, konkai no kaigi de teishutsu sareta.',
    '政府が導入を検討していると報じられた制度に反対する市民団体の声明が、各紙に掲載された。' => 'Seifu ga dounyuu wo kentou shite iru to houjirareta seido ni hantai suru shimin dantai no seimei ga, kakushi ni keisai sareta.',
    '研究者が長年収集してきたデータを分析した結果得られた知見は、これまでの常識を覆すものだった。' => 'Kenkyuusha ga naganen shuushuu shite kita deeta wo bunseki shita kekka erareta chiken wa, kore made no joushiki wo kutsugaesu mono datta.',
    '事故が起きた原因を究明するために設置された委員会がまとめた報告書が、来月公表される予定だ。' => 'Jiko ga okita gen\'in wo kyuumei suru tame ni setchi sareta iin kai ga matometa houkokusho ga, raigetsu kouhyou sareru yotei da.',
    '調査結果が発表された。それは傾向を示している。それを裏付けるデータが提出された。' => 'Chousa kekka ga happyou sareta. sore wa keikou wo shimeshite iru. sore wo urazukeru deeta ga teishutsu sareta.',
    'Struktur Penegasan Sebab dengan Klausa Terpisah ~のは~からだ' => 'Struktur Penegasan Sebab dengan Klausa Terpisah ~ no wa~ karada',
    'この政策が広く支持を集めているのは、単に経済的利益だけでなく、社会的公正への期待にも応えているからだ。' => 'Kono seisaku ga hiroku shiji wo atsumete iru no wa, tanni keizaiteki rieki dake de naku, shakaiteki kousei e no kitai ni mo kotaete irukara da.',
    '彼女が長年にわたって批判に耐えながらも研究を続けられたのは、自らの信念を貫く強さを持っていたからにほかならない。' => 'Kanojo ga naganen ni watatte hihan ni taenagara mo kenkyuu wo tsuzukerareta no wa, mizukara no shinnen wo tsuranuku tsuyosa wo motte itakara ni hoka naranai.',
    'この小説が時代を超えて読み継がれているのは、人間の普遍的な葛藤を描き出しているからだ。' => 'Kono shousetsu ga jidai wo koete yomitsugarete iru no wa, ningen no fuhenteki na kattou wo egakidashite irukara da.',
    '交渉が難航したのは、双方が互いの立場を譲らなかったばかりか、根本的な価値観の違いが浮き彫りになったからだった。' => 'Koushou ga nankou shita no wa, souhou ga tagai no tachiba wo yuzuranakatta bakari ka, konponteki na kachikan no chigai ga ukibori ni nattakara datta.',
    'この政策が広く支持を集めているのは、社会的公正への期待にも応えている。' => 'Kono seisaku ga hiroku shiji wo atsumete iru no wa, shakaiteki kousei e no kitai ni mo kotaete iru.',
    'Akhiran Klasik べし sebagai Penegasan Kewajiban' => 'Akhiran Klasik beshi sebagai Penegasan Kewajiban',
    '己の過ちを認め、常に謙虚たるべし。' => 'Onore no ayamachi wo mitome, tsune ni kenkyo tarubeshi.',
    '学生たるもの、規則を遵守すべし。' => 'Gakusei taru mono, kisoku wo junshu subeshi.',
    '危険物取扱者は、常に安全を最優先とすべし。' => 'Kikenbutsu toriatsukaisha wa, tsune ni anzen wo saiyuusen to subeshi.',
    '為せば成る、為さねば成らぬ、何事も成らぬは人の為さぬなりと心得るべし。' => 'Naseba naru, nasaneba naranu, nanigoto mo naranu wa hito no nasanunari to kokoroerubeshi.',
    '友人とのメールで「明日早く起きるべし。」のように日常的な文脈でべしを使った。' => 'Yuujin to no meeru de "ashita hayaku okirubeshi." no you ni nichijouteki na bunmyaku de beshi wo tsukatta.',
    'Struktur Kewajiban Tak Terelakkan ~ざるを得ない' => 'Struktur Kewajiban Tak Terelakkan ~ zaru wo enai',
    'これだけの証拠が揃った以上、彼の関与を認めざるを得ない。' => 'Kore dake no shouko ga sorotta ijou, kare no kan\'yo wo mitomezaru wo enai.',
    '資金繰りが悪化した以上、事業の縮小を決断せざるを得なかった。' => 'Shikin kuri ga akka shita ijou, jigyou no shukushou wo ketsudan sezaru wo enakatta.',
    '予想を上回る被害状況を前に、避難計画の見直しを迫られたと言わざるを得ない。' => 'Yosou wo uwamawaru higai joukyou wo mae ni, hinan keikaku no minaoshi wo semarareta to iwazaru wo enai.',
    '度重なる不祥事を受け、経営陣の責任を問わざるを得ない状況に至った。' => 'Tabikasanaru fushouji wo uke, keiei jin no sekinin wo towazaru wo enai joukyou ni itatta.',
    '資金繰りが悪化した以上、事業の縮小をしざるを得なかった。' => 'Shikin kuri ga akka shita ijou, jigyou no shukushou wo shizaru wo enakatta.',
    'Penutup Larangan Klasik ~べからず' => 'Penutup Larangan Klasik ~ bekarazu',
    '芝生に立ち入るべからず。' => 'Shibafu ni tachiirubekarazu.',
    'この扉、みだりに開くべからず。' => 'Kono tobira, midari ni hirakubekarazu.',
    '過去の栄光に驕るべからず、常に前進すべし。' => 'Kako no eikou ni ogorubekarazu, tsune ni zenshin subeshi.',
    '昨日、彼は芝生に立ち入るべからずでした。' => 'Kinou, kare wa shibafu ni tachiirubekarazudeshita.',
    'Konektor Klasik Kontinuatif ~つつ untuk Dua Aksi Simultan' => 'Konektor Klasik Kontinuatif ~tsutsu untuk Dua Aksi Simultan',
    '窓の外を眺めつつ、彼は静かに紅茶を飲んだ。' => 'Mado no soto wo nagametsutsu, kare wa shizuka ni koucha wo nonda.',
    '失敗を恐れつつも、彼女は新しい挑戦に踏み出した。' => 'Shippai wo osoretsutsu mo, kanojo wa atarashii chousen ni fumidashita.',
    '時代とともに価値観が変わりつつあることを、誰もが感じている。' => 'Jidai to tomo ni kachikan ga kawaritsutsu aru koto wo, dare mo ga kanjite iru.',
    '己の非を認めつつも、彼はなお言い訳を並べ立てた。' => 'Onore no hi wo mitometsutsu mo, kare wa nao iiwake wo narabetateta.',
    '私が説明しつつ、彼は資料を配った。' => 'Watashi ga setsumei shitsutsu, kare wa shiryou wo kubatta.',
    'Konektor Kausal Klasik ~がゆえに' => 'Konektor Kausal Klasik ~ ga yue ni',
    '人は不完全であるがゆえに、他者との関わりの中で成長できるのだ。' => 'Hito wa fukanzen de aru ga yue ni, tasha to no kakawari no naka de seichou dekiru no da.',
    'その理論はあまりにも単純であるがゆえに、多くの反証にさらされてきた。' => 'Sono riron wa amari ni mo tanjun de aru ga yue ni, ooku no hanshou ni sarasarete kita.',
    '我思う、ゆえに我あり。' => 'Ware omou, yue ni waga ari.',
    '権力は腐敗を招きやすい。ゆえに、それを監視する仕組みが不可欠である。' => 'Kenryoku wa fuhai wo manekiyasui. yue ni, sore wo kanshi suru shikumi ga fukaketsu de aru.',
    '今日は雨が降っているがゆえに、傘を持っていくよ。' => 'Kyou wa ame ga futte iruga yue ni, kasa wo motte iku yo.',
    '私の本です。' => 'Watashi no hon desu.',
    '私はご飯とみそ汁を食べました。' => 'Watashi wa gohan to miso shiru wo tabemashita.',
    'このカレーはよくないです。' => 'Kono karee wa yoku nai desu.',
    'この町は静かでした。' => 'Kono machi wa shizuka deshita.',
    '静かな公園に行きました。' => 'Shizuka na kouen ni ikimashita.',
    '東京は大阪ほど賑やかじゃないです。' => 'Tokyo wa Osaka hodo nigiyaka ja nai desu.',
    '本を買って、うちへ帰りました。' => 'Hon wo katte, uchi e kaerimashita.',
    '写真を撮ってください。' => 'Shashin wo totte kudasai.',
    '今、本を読んでいます。' => 'Ima, hon wo yonde imasu.',
    'ここに入ってはいけません。' => 'Koko ni haitte wa ikemasen.',
    '六時に家に帰ります。' => 'Roku ji ni ie ni kaerimasu.',
    '毎日、会社で働きます。' => 'Mainichi, kaisha de hatarakimasu.',
    '一緒に飲みましょう。' => 'Issho ni nomimashou.',
    '大阪へ行きます。' => 'Osaka e ikimasu.',
    '机の上に猫がいます。' => 'Tsukue no ue ni neko ga imasu.',
    '勉強したくないです。' => 'Benkyou shitaku nai desu.',
    '先生、ペンを貸していただけますか。' => 'Sensei, pen wo kashite itadakemasu ka.',
    '日本語の本が読めます。' => 'Nihon go no hon ga yomemasu.',
    '朝早く起きられます。' => 'Asa hayaku okiraremasu.',
    '私はサッカーができます。' => 'Watashi wa sakkaa ga dekimasu.',
    '私はピアノが弾けます。' => 'Watashi wa piano ga hajikemasu.',
    'この本はたくさんの人に読まれています。' => 'Kono hon wa takusan no hito ni yomarete imasu.',
    '妹にケーキが食べられました。' => 'Imouto ni keeki ga taberaremashita.',
    '雨に降られて、大変でした。' => 'Ame ni furarete, taihen deshita.',
    '私は野菜を食べさせられました。' => 'Watashi wa yasai wo tabesaseraremashita.',
    'あのレストランはおいしいそうです。' => 'Ano resutoran wa oishii sou desu.',
    'この天気はよさそうです。' => 'Kono tenki wa yosa sou desu.',
    'このケーキ、食べたことがないので「おいしそうです」と言いました。' => 'Kono keeki, tabeta koto ga nai no de "oishi sou desu" to iimashita.',
    '友達から聞いた話として「田中さんは元気だそうです」と言う。' => 'Tomodachi kara kiita hanashi to shite "Tanakasan wa genki da sou desu" to yuu.',
    '昨日、コーヒーを飲みすぎました。' => 'Kinou, koohii wo nomi sugimashita.',
    'この天気はよすぎます。' => 'Kono tenki wa yo sugimasu.',
    '残念ながら、行けません。' => 'Zannennagara, ikemasen.',
    '宿題をしてから、学校へ行きました。' => 'Shukudai wo shite kara, gakkou e ikimashita.',
    '私が勉強している間に、弟はゲームをしました。' => 'Watashi ga benkyou shite iru aida ni, otouto wa geemu wo shimashita.',
    '安いなら、買います。' => 'Yasuinara, kaimasu.',
    '山田先生なら、今職員室にいますよ。' => 'Yamada sensei nara, konshokuinshitsu ni imasu yo.',
    '休んだらどうですか。' => 'Yasundara dou desu ka.',
    '本を読めば、漢字がわかります。' => 'Hon wo yomeba, kanji ga wakarimasu.',
    '駅に着いたら、電話しました。' => 'Eki ni tsuitara, denwa shimashita.',
    '日本語が話せるように、毎日練習します。' => 'Nihon go ga hanaseru you ni, mainichi renshuu shimasu.',
    '風邪をひかないように、気をつけてください。' => 'Kaze wo hikanai you ni, ki wo tsukete kudasai.',
    'ピアノが弾けるようになりました。' => 'Piano ga hikeru you ni narimashita.',
    '彼は日本人のように日本語を話す。' => 'Kare wa Nihonnin no you ni Nihon go wo hanasu.',
    'このドアは自動で閉まるようにできている。' => 'Kono doa wa jidou de shimaru you ni dekite iru.',
    '日本語が話せるように、毎日練習しています。' => 'Nihon go ga hanaseru you ni, mainichi renshuu shite imasu.',
    '体調が悪いため、今日は休みます。' => 'Taichou ga warui tame, kyou wa yasumimasu.',
    '台風のため、運動会は中止になりました。' => 'Taifuu no tame, undou kai wa chuushi ni narimashita.',
    '大雨が降った。このため、川の水位が上がった。' => 'Ooame ga futta. kono tame, kawa no suii ga agatta.',
    '時間がないわけではない。' => 'Jikan ga nai wake de wa nai.',
    '休むわけにはいかない。' => 'Yasumu wake ni wa ikanai.',
    '彼が急に会社を辞めたのには、わけがある。' => 'Kare ga kyuu ni kaisha wo yameta no ni wa, wake ga aru.',
    '高ければ高いほど、品質がいいと思います。' => 'Takakereba takai hodo, hinshitsu ga ii to omoimasu.',
    'この料理は安ければ、おいしくもある。' => 'Kono ryouri wa yasukereba, oishiku mo aru.',
    '忙しければこそ、連絡しなかったのです。' => 'Isogashikereba koso, renraku shinakatta no desu.',
    'お金があればあったで、大丈夫です。' => 'Okane ga areba attade, daijoubu desu.',
    '失敗すればそれまでだ。' => 'Shippai sureba sore made da.',
    '明日、早く起きねばならない。' => 'Ashita, hayaku okineba naranai.',
    'このケーキは、言ってみれば、とても甘いです。' => 'Kono keeki wa, itte mireba, totemo amai desu.',
    '昨日、雨が降ったので、傘をさしました。' => 'Kinou, ame ga futta no de, kasa wo sashimashita.',
    'わからなかったら、先生に聞けばいいです。' => 'Wakaranakattara, sensei ni kikeba ii desu.',
    '休みなのに、どこにも行きませんでした。' => 'Yasumi na no ni, doko ni mo ikimasendeshita.',
    '彼は日本語が上手だ。なのに、外国人だとすぐわかる。' => 'Kare wa Nihon go ga jouzu da. na no ni, gaikokunin dato sugu wakaru.',
    '休めばよかったのに、彼は無理して働いた。' => 'Yasumeba yokatta no ni, kare wa muri shite hataraita.',
    '部長は忙しいのに、いつも手伝ってくださる。' => 'Buchou wa isogashii no ni, itsu mo tetsudatte kudasaru.',
    '毎日練習したので、試合に勝ちました。うれしかったです。' => 'Mainichi renshuu shita no de, shiai ni kachimashita. ureshikatta desu.',
    '体に悪いと知っているのに、たばこをやめられない。' => 'Karada ni warui to shitte iru no ni, tabako wo yamerarenai.',
    '私は大阪に転勤することになりました。' => 'Watashi wa Osaka ni tenkin suru koto ni narimashita.',
    'この学校では、制服を着ることになっている。だから、毎日着ています。' => 'Kono gakkou de wa, seifuku wo kiru koto ni natte iru. dakara, mainichi kite imasu.',
    'このたび、結婚することになりました、とみんなに報告した。' => 'Kono tabi, kekkon suru koto ni narimashita, to minna ni houkoku shita.',
    '会社の命令で、大阪に転勤することになりました。' => 'Kaisha no meirei de, Osaka ni tenkin suru koto ni narimashita.',
    'A：「二人は結婚したの？」B：「うん、まあ、そういうことになったね。」' => 'A: "futari wa kekkon shita no?" B: "un, maa, sou iu koto ni natta ne."',
    '毎日運動することにします。' => 'Mainichi undou suru koto ni shimasu.',
    '私は健康のためにずっと野菜をたくさん食べることにしている。' => 'Watashi wa kenkou no tame ni zutto yasai wo takusan taberu koto ni shite iru.',
    '昨日、友達と相談して、旅行に行かないことにした。' => 'Kinou, tomodachi to soudan shite, ryokou ni ikanai koto ni shita.',
    '会社の都合で、私は海外に転勤することになった。' => 'Kaisha no tsugou de, watashi wa kaigai ni tenkin suru koto ni natta.',
    '会議は来週にすることにしましょう。' => 'Kaigi wa raishuu ni suru koto ni shimashou.',
    '私はそれを言わなかったことにする。' => 'Watashi wa sore wo iwanakatta koto ni suru.',
    '今のところ、彼が知らないことにしておく、でも来週には話すつもりだ。' => 'Ima no tokoro, kare ga shiranai koto ni shite oku, de mo raishuu ni wa hanasu tsumori da.',
    '毎朝走ることにしているが、今日は走れなかった。' => 'Maiasa hashiru koto ni shite iruga, kyou wa hashirenakatta.',
    '毎日、できるだけ早く寝るようにしています。' => 'Mainichi, dekiru dake hayaku neru you ni shite imasu.',
    '田中さんは実は女性だったらしいです。' => 'Tanakasan wa jitsu wa josei dattarashii desu.',
    'あなたらしくなかったですよ。' => 'Anatarashiku nakatta desu yo.',
    '目の前で雨が降っているのを見て「雨が降っているようだ」と言った。' => 'Me no mae de ame ga futte iru no wo mite "ame ga futte iru you da" to itta.',
    '空を見て「雨が降りそうだ」または「雨が降るようだ」と言った。' => 'Sora wo mite "ame ga furi sou da" mata wa "ame ga furu you da" to itta.',
    'あの店は美味しいらしいですが。' => 'Ano mise wa oishiirashii desuga.',
    '聞いた話では、彼は医者らしい。 または 彼はいかにも医者らしい態度だ。' => 'Kiita hanashi de wa, kare wa isha rashii. mata wa kare wa ikani mo isharashii taido da.',
    '隣の田中さん、来月引っ越すらしいですよ。' => 'Tonari no Tanakasan, raigetsu hikkosurashii desu yo.',
    '彼は学生のようだ。' => 'Kare wa gakusei no you da.',
    '自分で味見して「何か足りないようだ」と言った。' => 'Jibun de ajimi shite "nan ka tarinai you da" to itta.',
    'このケーキ、とても美味しそうだ、まだ食べていないけど見ただけで。' => 'Kono keeki, totemo oishi sou da, mada tabete inaikedo mita dake de.',
    '毎日運動するわけではない。' => 'Mainichi undou suru wake de wa nai.',
    '必ずしも成功するわけではない。' => 'Kanarazu shimo seikou suru wake de wa nai.',
    '決して行かないわけではない。都合がつけば行くつもりだ。' => 'Kesshite ikanai wake de wa nai. tsugou ga tsukeba iku tsumori da.',
    'みんなが寿司が好きなわけではない。' => 'Minna ga sushi ga suki na wake de wa nai.',
    'お金があるからといって、幸せなわけではない。' => 'Okane ga arukara to itte, shiawase na wake de wa nai.',
    '彼が悪人だというわけではない。' => 'Kare ga akunin da to iu wake de wa nai.',
    '反対しているわけではないが、積極的に賛成というわけでもない。' => 'Hantai shite iru wake de wa naiga, sekkyokuteki ni sansei to iu wake de mo nai.',
    '希望がないわけではない。' => 'Kibou ga nai wake de wa nai.',
    '別に、彼のことが好きなわけではない。' => 'Betsu ni, kare no koto ga suki na wake de wa nai.',
    '忙しいわけでもないので、時間がある。' => 'Isogashii wake de mo nai no de, jikan ga aru.',
    '明日は晴れに違いない。' => 'Ashita wa hare ni chigai nai.',
    '彼は昨日忙しかったに違いない。' => 'Kare wa kinou isogashikatta ni chigai nai.',
    '今日は疲れたから、早く寝るに違いない。' => 'Kyou wa tsukaretakara, hayaku neru ni chigai nai.',
    'きっと雨が降るに違いない。' => 'Kitto ame ga furu ni chigai nai.',
    '彼が来なかったのに違いない。' => 'Kare ga konakatta no ni chigai nai.',
    '会議の資料によると、会議は10時に始まるはずだ。' => 'Kaigi no shiryou ni yoruto, kaigi wa 10 ji ni hajimaru hazu da.',
    'もしかしたら、彼が犯人かもしれない。' => 'Moshi ka shitara, kare ga hannin ka mo shirenai.',
    '彼は昨日勉強しなかったに違いない。' => 'Kare wa kinou benkyou shinakatta ni chigai nai.',
    '明日は晴れそうなので、旅行に行こうと思う。' => 'Ashita wa hare sou na no de, ryokou ni ikou to omou.',
    'この部屋は狭いものの、日当たりがいい。' => 'Kono heya wa semai mono no, hiatari ga ii.',
    '彼は有名であるものの、まだ苦労している。' => 'Kare wa yuumei de aru mono no, mada kurou shite iru.',
    '運動が大切だとはいうものの、続けられない。' => 'Undou ga taisetsu da to wa iu mono no, tsuzukerarenai.',
    '謝るべきだとは思っているが、なかなか勇気が出ない。' => 'Ayamarubekida to wa omotte iruga, nakanaka yuuki ga denai.',
    '手術は成功したものの、まだ完全には回復していない。' => 'Shujutsu wa seikou shita mono no, mada kanzen ni wa kaifuku shite inai.',
    '法律が施行されたものの、依然として問題は解決していない。' => 'Houritsu ga shikou sareta mono no, izen to shite mondai wa kaiketsu shite inai.',
    'ねえ、疲れているけど、遊びに行かない？' => 'Nee, tsukarete irukedo, asobi ni ikanai?',
    '計画通りに進むはずだったものの、実際には多くのずれが生じた。' => 'Keikaku toori ni susumu hazu datta mono no, jissai ni wa ooku no zure ga shoujita.',
    'この規則に基づいて説明します。' => 'Kono kisoku ni motozuite setsumei shimasu.',
    '法律に基づいて、この罰金が決まった。' => 'Houritsu ni motozuite, kono bakkin ga kimatta.',
    'データに基づいて、市場動向を分析した。' => 'Deeta ni motozuite, shijou doukou wo bunseki shita.',
    '経験に基づいて、こうだと考えられる。' => 'Keiken ni motozuite, kou da to kangaerareru.',
    'この映画は実話に基づいています。' => 'Kono eiga wa jitsuwa ni motozuite imasu.',
    '契約に基づいて、支払いを求めます。' => 'Keiyaku ni motozuite, shiharai wo motomemasu.',
    '基準に基づいて判断すれば、彼は合格するはずだ。' => 'Kijun ni motozuite handan sureba, kare wa goukaku suru hazu da.',
    '台風によって、多くの家が壊れた。' => 'Taifuu ni yotte, ooku no ie ga kowareta.',
    '質問に対して、先生は丁寧に答えた。' => 'Shitsumon ni taishite, sensei wa teinei ni kotaeta.',
    'この問題は私にとって難しいです。' => 'Kono mondai wa watashi ni totte muzukashii desu.',
    '高齢者に対する態度が変わってきている。' => 'Koureisha ni taisuru taido ga kawatte kite iru.',
    'ハサミで紙を切った。' => 'Hasami de kami wo kitta.',
    'この製品は最新の技術によって作られている、と正式な報告書に書いた。' => 'Kono seihin wa saishin no gijutsu ni yotte tsukurarete iru, to seishiki na houkokusho ni kaita.',
    '私の趣味は映画を見ることです。' => 'Watashi no shumi wa eiga wo miru koto desu.',
    '環境問題に関する報告書を読んだ。' => 'Kankyou mondai ni kansuru houkokusho wo yonda.',
    '品質は良いが、値段に関しては高すぎる。' => 'Hinshitsu wa yoiga, nedan ni kanshite wa taka sugiru.',
    '友達と週末の旅行について話した。' => 'Tomodachi to shuumatsu no ryokou ni tsuite hanashita.',
    '彼は上司に対して怒っている。' => 'Kare wa joushi ni taishite okotte iru.',
    '新製品に関する情報をホームページに載せました。' => 'Shinseihin ni kansuru jouhou wo hoomu peeji ni nosemashita.',
    '速さに関して言えば、この車が一番だ。' => 'Hayasa ni kanshite ieba, kono kuruma ga ichiban da.',
    '天気予報に関する限り、明日は晴れるでしょう。' => 'Tenki yohou ni kansuru kagiri, ashita wa harerudeshou.',
    '彼は何に関しても詳しい。' => 'Kare wa nan ni kanshite mo kuwashii.',
    'じゃあ、値段については、後で言うね。' => 'Jaa, nedan ni tsuite wa, ato de yuu ne.',
    '彼は経済に関して詳しい。' => 'Kare wa keizai ni kanshite kuwashii.',
    'この値上げは学生にとって大きな負担になる。' => 'Kono neage wa gakusei ni totte ookina futan ni naru.',
    '雨が降りそうだったので、傘を持って行った。' => 'Ame ga furi sou datta no de, kasa wo motte itta.',
    'たくさん食べたので、太った。' => 'Takusan tabeta no de, futotta.',
    'ねえ、雨が降るから、公園行くのやめない?' => 'Nee, ame ga furukara, kouen iku no yamenai?',
    '努力を続けるに伴って、彼の成績が上がった。' => 'Doryoku wo tsuzukeru ni tomonatte, kare no seiseki ga agatta.',
    '規則の変更に伴って、社員に説明会を開いてください。' => 'Kisoku no henkou ni tomonatte, shain ni setsumei kai wo hiraite kudasai.',
    '今日は雨が降っていたので、傘を持ってきました。' => 'Kyou wa ame ga futte ita no de, kasa wo motte kimashita.',
    '気温が上昇しているにもかかわらず、アイスクリームの売り上げは伸びていない。' => 'Kion ga joushou shite iru ni mo kakawarazu, aisu kuriimu no uriage wa nobite inai.',
    '経験年数に応じて、給料が決められる。' => 'Keiken nensuu ni oujite, kyuuryou ga kimerareru.',
    '頭痛のため、今日は会社を休みます。' => 'Zutsuu no tame, kyou wa kaisha wo yasumimasu.',
    '彼は失恋して、すぐに泣き出した。' => 'Kare wa shitsuren shite, sugu ni naki dashita.',
    '明日、友達と遊ぶときに、公園で待ち合わせした。' => 'Ashita, tomodachi to asobu toki ni, kouen de machiawase shita.',
    'これまでのデータを踏まえて、結論を出した。' => 'Kore made no deeta wo fumaete, ketsuron wo dashita.',
    'ご飯を食べる前に、手を洗った。' => 'Gohan wo taberu mae ni, te wo aratta.',
    'このペンで書きます。' => 'Kono pen de kakimasu.',
    '雨が降ったので、傘を差した。' => 'Ame ga futta no de, kasa wo sashita.',
    '私は猫が好きなのみならず、犬も好きだ。' => 'Watashi wa neko ga suki na nomi narazu, inu mo suki da.',
    '天気予報に鑑みて、傘を持って行った。' => 'Tenki yohou ni kangamite, kasa wo motte itta.',
    '彼は成功を収めた。' => 'Kare wa seikou wo osameta.',
    '学生たる者、勉学に励むべきだ。' => 'Gakusei taru mono, bengaku ni hagemubekida.',
    '遊びに行くために、準備した。' => 'Asobi ni iku tame ni, junbi shita.',
    'この結果は失敗だと言わざるを得ない。' => 'Kono kekka wa shippai da to iwazaru wo enai.',
    '彼が遅刻したのは、寝坊したからに他ならない。' => 'Kare ga chikoku shita no wa, nebou shitakara ni hoka naranai.',
    '今日のラーメンは非常においしいと言っても過言ではない。' => 'Kyou no raamen wa hijou ni oishii to itte mo kagon de wa nai.',
    '状況が変わったので、対応をせざるを得ない。' => 'Joukyou ga kawatta no de, taiou wo sezaru wo enai.',
    '信頼するに足る人だ。' => 'Shinrai suru ni taru hito da.',
    '彼はいつも笑顔で、人を明るくする傾向がある。' => 'Kare wa itsu mo egao de, hito wo akaruku suru keikou ga aru.',
    'これは仮説にすぎない。' => 'Kore wa kasetsu ni suginai.',
    '彼は毎日走り続けている。' => 'Kare wa mainichi hashiri tsuzukete iru.',
    '彼の意見に、共感を禁じ得ない。' => 'Kare no iken ni, kyoukan wo kinji enai.',
    '頑張ることなくして、目標は達成できない。' => 'Ganbaru koto naku shite, mokuhyou wa tassei dekinai.',
    '誠に申し訳ございませんが、そちらはいたしかねます。' => 'Makoto ni moushiwake gozaimasenga, sochira wa itashikane masu.',
    'その資料は拝見いたしました。' => 'Sono shiryou wa haiken itashimashita.',
    '明日、友達と映画を見ることになりました。' => 'Ashita, tomodachi to eiga wo miru koto ni narimashita.',
    '資料をお送りいただければ幸いです。' => 'Shiryou wo ookuri itadakereba saiwai desu.',
    'お手伝いのほど、よろしくお願いいたします。' => 'Otetsudai no hodo, yoroshiku onegai itashimasu.',
    'この件は対応いたしかねる場合がございます。' => 'Kono ken wa taiou itashikaneru baai ga gozaimasu.',
