    '彼は泥まみれで帰ってきた。' => 'Kare wa doromamire de kaette kita.',
    '彼は先生めいた話し方をする。' => 'Kare wa senseimei ta hanashikata wo suru.',
    '散歩がてら、買い物をする。' => 'Sanpogatera, kaimono wo suru.',
    '散歩がてら、買い物をした。' => 'Sanpogatera, kaimono wo shita.',
    '彼は背が高いのにひきかえ、私は背が低い。' => 'Kare wa se ga takai no ni hikikae, watashi wa se ga hikui.',
