    '頑張ることなくして成功はない。' => 'Ganbaru koto naku shite seikou wa nai.',
    '彼女は歌が上手だ。' => 'Kanojo wa uta ga jouzu da.',
    'このラーメンは食べやすい。' => 'Kono raamen wa tabeyasui.',
    '明日は雨が降ると思う。' => 'Ashita wa ame ga furu to omou.',
    '友達に「遅刻したら罰金だよ！」と冗談を言った。' => 'Tomodachi ni "chikoku shitara bakkin da yo!" to joudan wo itta.',
