    '記事の見出しとして「新技術、発表される」または「新技術を発表」と書いた。' => 'Kiji no midashi to shite "shingijutsu, happyou sareru" mata wa "shingijutsu wo happyou" to kaita.',
    '長年にわたって住民が反対していた計画が、先月ついに中止された。' => 'Naganen ni watatte juumin ga hantai shite ita keikaku ga, sengetsu tsuini chuushi sareta.',
    '昨日、友達とカフェに行った。' => 'Kinou, tomodachi to kafe ni itta.',
