    'あの映画は、素晴らしかった。' => 'Ano eiga wa, subarashikatta.',
    '休みの日は、映画を見たり本を読んだりする。' => 'Yasumi no hi wa, eiga wo mi tari hon wo yon dari suru.',
    'この部屋は狭いし暗いし、あまり好きじゃない。' => 'Kono heya wa semaishi kuraishi, amari suki ja nai.',
