    '雨が降ったので、試合が中止になった。' => 'Ame ga futta no de, shiai ga chuushi ni natta.',
    '報告書には通常の語順で「あの日見た光は消えた。」と記述すべきである。' => 'Houkokusho ni wa tsuujou no gojun de "ano hi mita hikari wa kieta." to kijutsu subekide aru.',
    '反語表現は答えを求める文ではないため、相手が沈黙するのは自然な反応であり、驚く必要はない。' => 'Hango hyougen wa kotae wo motomeru bun de wa nai tame, aite ga chinmoku suru no wa shizen na hannou de ari, odoroku hitsuyou wa nai.',
    '光もあれば影もある、それが人生だ。' => 'Hikari mo areba kage mo aru, sore ga jinsei da.',
    '日常会話では「勉強しないでテストに合格できるわけがない」のように口語的な表現を使うべきである。' => 'Nichijou kaiwa de wa "benkyou shinaide tesuto ni goukaku dekiru wake ga nai" no you ni kougoteki na hyougen wo tsukaubekide aru.',
    '学術論文では「本研究が示すのは、新たな可能性である。」のように述語を明示して文を完結させるべきである。' => 'Gakujutsu ronbun de wa "honkenkyuu ga shimesu no wa, arata na kanousei de aru." no you ni jutsugo wo meiji shite bun wo kanketsu saserubekide aru.',
    '学術的な文章では「この理論には再検討の余地があると考えられる。」のように主張を和らげる構造を用いるべきである。' => 'Gakujutsuteki na bunshou de wa "kono riron ni wa saikentou no yochi ga aru to kangaerareru." no you ni shuchou wo yawarageru kouzou wo mochiirubekide aru.',
    '仮にこの政策が効果を上げたとしても、長期的な弊害を軽視した結果にほかならない。' => 'Kari ni kono seisaku ga kouka wo ageta to shite mo, choukiteki na heigai wo keishi shita kekka ni hoka naranai.',
    '新薬の副作用は軽微であるとの報告がある。' => 'Shin\'yaku no fukusayou wa keibi de aru to no houkoku ga aru.',
    '賛成派は経済効果が期待できるという考えを示したが、反対派は環境への影響を懸念するという立場を崩さなかった。' => 'Sanseiha wa keizai kouka ga kitai dekiru to iu kangae wo shimeshitaga, hantaiha wa kankyou e no eikyou wo kenen suru to iu tachiba wo kuzusanakatta.',
    '予算が限られているため、全ての要望に応えられるならば理想的であるものの、優先順位をつけざるを得ない。' => 'Yosan ga kagirarete iru tame, subete no youbou ni kotaerarerunaraba risouteki de aru mono no, yuusen jun\'i wo tsukezaru wo enai.',
    '若年層の投票率が低下しているということは、政治への関心が薄れていることを意味しない。' => 'Jakunen sou no touhyou ritsu ga teika shite iru to iu koto wa, seiji e no kanshin ga usurete iru koto wo imi shinai.',
    '先週発表された調査結果が示している傾向を裏付ける新たなデータが提出された。' => 'Senshuu happyou sareta chousa kekka ga shimeshite iru keikou wo urazukeru arata na deeta ga teishutsu sareta.',
    'この政策が広く支持を集めているのは、社会的公正への期待にも応えているからだ。' => 'Kono seisaku ga hiroku shiji wo atsumete iru no wa, shakaiteki kousei e no kitai ni mo kotaete irukara da.',
    '日常会話やカジュアルな文脈では「明日早く起きるべきだよ。」のように現代語のべきだを使うのが自然である。' => 'Nichijou kaiwa ya kajuaru na bunmyaku de wa "ashita hayaku okirubekida yo." no you ni gendai go no bekida wo tsukau no ga shizen de aru.',
    '資金繰りが悪化した以上、事業の縮小をせざるを得なかった。' => 'Shikin kuri ga akka shita ijou, jigyou no shukushou wo sezaru wo enakatta.',
    '彼は芝生に立ち入ってはいけなかった。' => 'Kare wa shibafu ni tachiitte wa ikenakatta.',
    '私が説明する間に、彼は資料を配った。' => 'Watashi ga setsumei suru aida ni, kare wa shiryou wo kubatta.',
